begin;
    with j as (select * from jsonb_to_recordset($law7v020$[{"code_id":"KoAP_RF","article_number":"7.17","version_date":"2001-12-30","article_text":"Умышленное уничтожение или повреждение чужого имущества, если эти действия не повлекли причинение значительного ущерба, -\n\nвлечет наложение административного штрафа в размере от трехсот до пятисот рублей.  (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 7.17. Уничтожение или повреждение чужого имущества","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0cc2c58256e3fbbad8262c00d59cc7cc0df3b420186c0ebf8d955e1467ff4201"},{"code_id":"KoAP_RF","article_number":"7.18","version_date":"2001-12-30","article_text":"Нарушение правил хранения, закупки или рационального использования зерна и продуктов его переработки, а также правил производства продуктов переработки зерна (за исключением случаев, когда такие правила содержатся в технических регламентах) -  (В редакции Федерального закона от 18.07.2011 № 237-ФЗ)\n\nвлечет предупреждение или наложение административного штрафа на граждан в размере от пятисот до одной тысячи рублей; на должностных лиц - от одной тысячи до двух тысяч рублей; на юридических лиц - от десяти тысяч до двадцати тысяч рублей.  (В редакции федеральных законов от 22.06.2007 № 116-ФЗ; от 27.07.2010 № 239-ФЗ)","article_title":"Статья 7.18. Нарушение правил хранения, закупки или рационального использования зерна и продуктов его переработки, правил производства продуктов переработки зерна","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fd3d561a549be1a56f345b9d16c4aeb095e16a9817865b745dfd970806f352ab"},{"code_id":"KoAP_RF","article_number":"7.19","version_date":"2001-12-30","article_text":"1. Самовольное подключение к электрическим сетям, тепловым сетям, нефтепроводам, нефтепродуктопроводам, газопроводам либо самовольное (безучетное) использование электрической, тепловой энергии, нефти, газа или нефтепродуктов, если эти действия не содержат признаков уголовно наказуемого деяния, -\n\nвлечет наложение административного штрафа на граждан в размере от десяти тысяч до пятнадцати тысяч рублей; на должностных лиц - от тридцати тысяч до восьмидесяти тысяч рублей или дисквалификацию на срок от одного года до двух лет; на юридических лиц - от ста тысяч до двухсот тысяч рублей.\n\n2. Повторное совершение административного правонарушения, предусмотренного частью 1 настоящей статьи, выразившегося в самовольном подключении к электрическим сетям, тепловым сетям либо в самовольном (безучетном) использовании электрической, тепловой энергии, нефти, газа или нефтепродуктов, -\n\nвлечет наложение административного штрафа на граждан в размере от пятнадцати тысяч до тридцати тысяч рублей; на должностных лиц - от восьмидесяти тысяч до двухсот тысяч рублей или дисквалификацию на срок от двух до трех лет; на юридических лиц - от двухсот тысяч до трехсот тысяч рублей.\n\n3. Повторное совершение административного правонарушения, предусмотренного частью 1 настоящей статьи, выразившегося в самовольном подключении к нефтепроводам, нефтепродуктопроводам, газопроводам, -\n\nвлечет наложение административного штрафа на юридических лиц в размере от трехсот тысяч до четырехсот тысяч рублей.\n\n(Статья в редакции Федерального закона от 14.07.2022 № 289-ФЗ)","article_title":"Статья 7.19. Самовольное подключение и использованиеэлектрической, тепловой энергии, нефти или газа","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1690467fd4de8570a6da8d7c28f3e6f2a5f1d1e43ea0a1bbff9f2d3363443148"},{"code_id":"KoAP_RF","article_number":"7.2","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 28.12.2009 № 380-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от трех тысяч до пяти тысяч рублей; на должностных лиц - от пяти тысяч до десяти тысяч рублей; на юридических лиц - от пятидесяти тысяч до ста тысяч рублей. (В редакции Федерального закона от 21.10.2013 № 282-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от пяти тысяч до десяти тысяч рублей; на должностных лиц - от десяти тысяч до пятидесяти тысяч рублей; на юридических лиц - от пятидесяти тысяч до двухсот тысяч рублей.\n\n(Часть в редакции Федерального закона от 08.03.2015 № 46-ФЗ)\n\nвлечет предупреждение или наложение административного штрафа в размере от одной тысячи до пяти тысяч рублей. (В редакции Федерального закона от 08.03.2015 № 46-ФЗ)","article_title":"Статья 7.2. Уничтожение или повреждение специальных знаков","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"87c92cd6f4d20e40a224303607a4f1fa1d9c4fa0f26fcf73c93a0bb44545e028"},{"code_id":"KoAP_RF","article_number":"7.20","version_date":"2001-12-30","article_text":"Самовольное подключение к централизованным системам водоснабжения и водоотведения и (или) самовольное пользование такими системами, если эти действия не содержат признаков уголовно наказуемого деяния, -\n\nвлекут наложение административного штрафа на граждан в размере от десяти тысяч до пятнадцати тысяч рублей; на должностных лиц - от тридцати тысяч до восьмидесяти тысяч рублей; на юридических лиц - от ста тысяч до двухсот тысяч рублей.\n\n(Статья в редакции Федерального закона от 08.08.2024 № 241-ФЗ)","article_title":"Статья 7.20. Самовольное подключение к централизованным системам водоснабжения и водоотведения и (или) самовольное пользование такими системами","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3ebf9ecec621171e726fc9eafcb09b495c4bab66ba84028c64f8c059cbee22b6"},{"code_id":"KoAP_RF","article_number":"7.21","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 24.04.2020 № 133-ФЗ)\n\nвлечет предупреждение или наложение административного штрафа на граждан в размере от одной тысячи до одной тысячи пятисот рублей; на должностных лиц - от двух тысяч до трех тысяч рублей; на юридических лиц - от двадцати тысяч до тридцати тысяч рублей. (В редакции федеральных законов от 22.06.2007 № 116-ФЗ, от 24.04.2020 № 133-ФЗ)\n\nвлекут наложение административного штрафа на граждан в размере от двух тысяч до двух тысяч пятисот рублей; на должностных лиц - от четырех тысяч до пяти тысяч рублей; на юридических лиц - от сорока тысяч до пятидесяти тысяч рублей. (В редакции федеральных законов от 22.06.2007 № 116-ФЗ, от 24.04.2020 № 133-ФЗ)\n\nПримечание. За административные правонарушения, предусмотренные настоящей статьей, лица, осуществляющие предпринимательскую деятельность без образования юридического лица, несут административную ответственность как юридические лица. (Дополнение примечанием - Федеральный закон от 24.04.2020 № 133-ФЗ)","article_title":"Статья 7.21. Нарушение правил пользования жилыми помещениями. Самовольные переустройство и (или) перепланировка помещения в многоквартирном доме","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d8ef767159be91fe9e113a21ff2c3e77d0f18645deb94fc799316774b24f41cd"},{"code_id":"KoAP_RF","article_number":"7.22","version_date":"2001-12-30","article_text":"Нарушение лицами, ответственными за содержание жилых домов и (или) жилых помещений, правил содержания и ремонта жилых домов и (или) жилых помещений либо порядка и правил признания их непригодными для постоянного проживания и перевода их в нежилые, а равно переустройство и (или) перепланировка жилых домов и (или) жилых помещений без согласия нанимателя (собственника), если переустройство и (или) перепланировка существенно изменяют условия пользования жилым домом и (или) жилым помещением, -   (В редакции Федерального закона от 28.12.2009 № 380-ФЗ)\n\nвлечет наложение административного штрафа на должностных лиц в размере от четырех тысяч до пяти тысяч рублей; на юридических лиц - от сорока тысяч до пятидесяти тысяч рублей.  (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 7.22. Нарушение правил содержания и ремонта жилых домов и (или) жилых помещений","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b7e3b3104159e9a08dad3411cc93b8371304b0cd82bd8f6e3627c0dedbadc36f"},{"code_id":"KoAP_RF","article_number":"7.23","version_date":"2001-12-30","article_text":"1. Нарушение нормативного уровня или режима обеспечения населения коммунальными услугами, за исключением случаев, предусмотренных частью 2 настоящей статьи, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от пятисот до одной тысячи рублей; на юридических лиц - от пяти тысяч до десяти тысяч рублей.\n\n2. Нарушение нормативного уровня или режима обеспечения населения коммунальными услугами лицами, осуществляющими поставки ресурсов, необходимых для предоставления коммунальных услуг, -\n\nвлечет предупреждение или наложение административного штрафа на должностных лиц в размере от пяти тысяч до десяти тысяч рублей; на юридических лиц - от тридцати тысяч до пятидесяти тысяч рублей.\n\n3. Повторное совершение административного правонарушения, предусмотренного частью 2 настоящей статьи, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от десяти тысяч до тридцати тысяч рублей; на юридических лиц - от пятидесяти тысяч до ста тысяч рублей.\n\nПримечание. За административные правонарушения, предусмотренные настоящей статьей, лица, осуществляющие предпринимательскую деятельность без образования юридического лица, несут административную ответственность как юридические лица.\n\n(Статья в редакции  Федерального закона от 29.05.2024 № 116-ФЗ)","article_title":"Статья 7.23. Нарушение нормативного уровня или режима обеспечения населения коммунальными услугами","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2f9b4f174bf709817e86f40a6d4e883b5bfa291431898d7d0273eb0dda037faa"},{"code_id":"KoAP_RF","article_number":"7.231","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 06.12.2011 № 403-ФЗ) (Утратила силу - Федеральный закон от 21.07.2014 № 263-ФЗ)","article_title":"Статья 7.231. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b08c23a14a97f33b8410809275f44b27c335321d64af4fe07bc4ed8888a1e3a8"},{"code_id":"KoAP_RF","article_number":"7.232","version_date":"2001-12-30","article_text":"1. Воспрепятствование деятельности по управлению многоквартирным домом, выразившееся в отказе от передачи технической документации на многоквартирный дом и иных связанных с управлением таким многоквартирным домом документов управляющей организации, товариществу собственников жилья, жилищному кооперативу, жилищно-строительному кооперативу, иному специализированному потребительскому кооперативу или одному из собственников помещений в многоквартирном доме, либо в уклонении от передачи таких документов указанным лицам, либо в нарушении предусмотренных федеральными законами и принятыми в соответствии с ними иными нормативными правовыми актами порядка и сроков передачи указанных документов, -\n\nвлечет наложение административного штрафа на граждан в размере от двух тысяч до пяти тысяч рублей; на должностных лиц - от тридцати тысяч до сорока тысяч рублей; на юридических лиц - от ста пятидесяти тысяч до двухсот тысяч рублей.\n\n2. Совершение административного правонарушения, предусмотренного частью 1 настоящей статьи, должностным лицом, ранее подвергнутым административному наказанию за аналогичное административное правонарушение, -\n\nвлечет дисквалификацию на срок от одного года до трех лет.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 121-ФЗ)","article_title":"Статья 7.232. Нарушение требований законодательства о передаче технической документации на многоквартирный дом и иных связанных с управлением таким многоквартирным домом документов","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5e49411851731c2b867b2145b47b976ad6c55a0d38898177e7323edc12eb2bb9"},{"code_id":"KoAP_RF","article_number":"7.233","version_date":"2001-12-30","article_text":"1. Нарушение организациями и индивидуальными предпринимателями, осуществляющими предпринимательскую деятельность по управлению многоквартирными домами на основании договоров управления многоквартирными домами, правил осуществления предпринимательской деятельности по управлению многоквартирными домами -\n\nвлечет наложение административного штрафа на должностных лиц в размере от пятидесяти тысяч до ста тысяч рублей или дисквалификацию на срок до трех лет; на юридических лиц - от ста пятидесяти тысяч до двухсот пятидесяти тысяч рублей.\n\n2. Невыполнение указанными в части 1 настоящей статьи лицами обязанностей, предусмотренных правилами осуществления предпринимательской деятельности по управлению многоквартирными домами, в период прекращения действия лицензии на осуществление предпринимательской деятельности по управлению многоквартирными домами или ее аннулирования, если указанные лица обязаны надлежащим образом осуществлять предпринимательскую деятельность по управлению многоквартирными домами, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от ста тысяч до двухсот тысяч рублей или дисквалификацию на срок до трех лет; на индивидуальных предпринимателей - от ста пятидесяти тысяч до пятисот тысяч рублей или дисквалификацию на срок до трех лет; на юридических лиц - от ста пятидесяти тысяч до пятисот тысяч рублей.\n\nПримечание. За административные правонарушения, предусмотренные настоящей статьей, лица, осуществляющие предпринимательскую деятельность без образования юридического лица, несут административную ответственность как юридические лица.\n\n(Дополнение статьей - Федеральный закон от 21.07.2014 № 255-ФЗ)","article_title":"Статья 7.233. Нарушение правил осуществления предпринимательской деятельности по управлению многоквартирными домами","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c3b0b117f96cb9dcc48ab533306c4ac52db7311b9534e9a12f1c2ba3bf40ccca"},{"code_id":"KoAP_RF","article_number":"7.24","version_date":"2001-12-30","article_text":"1. Распоряжение объектом нежилого фонда, находящимся в федеральной собственности, без разрешения специально уполномоченного федерального органа исполнительной власти -\n\nвлечет наложение административного штрафа на должностных лиц в размере от четырех тысяч до пяти тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n2. Использование находящегося в федеральной собственности объекта нежилого фонда без надлежаще оформленных документов либо с нарушением установленных норм и правил эксплуатации и содержания объектов нежилого фонда -\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи до одной тысячи пятисот рублей; на должностных лиц - от двух тысяч до трех тысяч рублей; на юридических лиц - от двадцати тысяч до тридцати тысяч рублей.  (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 7.24. Нарушение порядка распоряжения объектом нежилого фонда, находящимся в федеральной собственности, и использования указанного объекта","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a44ec232aa25dab1e8eecaf0de34dbf6ed311c8959f86c0a150eaedf6a9f105d"},{"code_id":"KoAP_RF","article_number":"7.25","version_date":"2001-12-30","article_text":"Уклонение от безвозмездной передачи одного экземпляра копий геодезических или картографических материалов и данных в государственный картографо-геодезический фонд Российской Федерации -\n\nвлечет наложение административного штрафа на граждан в размере от ста до трехсот рублей; на должностных лиц - от трехсот до пятисот рублей; на юридических лиц - от трех тысяч до пяти тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 7.25. Уклонение от безвозмездной передачи копий геодезических или картографических материалов и данных в государственный картографо-геодезический фонд Российской Федерации","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d0e4a7d67f2b4350c4c27c660f9d609d4a8fc7b807b16744084f0a0cbd9ffaa1"},{"code_id":"KoAP_RF","article_number":"7.26","version_date":"2001-12-30","article_text":"Небрежное хранение пользователем материалов и данных государственного картографо-геодезического фонда Российской Федерации, повлекшее утрату таких материалов и данных, -\n\nвлечет наложение административного штрафа на граждан в размере от трехсот до пятисот рублей; на должностных лиц - от пятисот до одной тысячи рублей.  (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 7.26. Утрата материалов и данных государственного картографо-геодезического фонда Российской Федерации","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cf46b5b55b36fc6c3e25c49000e47fb147db5c3bb95a180e4c87c59d4f3e7a17"},{"code_id":"KoAP_RF","article_number":"7.27","version_date":"2001-12-30","article_text":"1. Мелкое хищение чужого имущества, стоимость которого не превышает одну тысячу рублей, путем кражи, мошенничества, присвоения или растраты при отсутствии признаков преступлений, предусмотренных частями второй, третьей и четвертой статьи 158, статьей 1581, частями\n\nвторой, третьей и четвертой статьи 159, частями второй, третьей и четвертой статьи 1591, частями второй, третьей и четвертой статьи 1592, частями второй, третьей и четвертой статьи 1593, частями второй, третьей и четвертой статьи 1595, частями второй, третьей и четвертой статьи 1596 и частями второй и третьей статьи 160 Уголовного кодекса Российской Федерации, за исключением случаев, предусмотренных статьями 7.20 и 14.153 настоящего Кодекса, - (В редакции  федеральных законов от 05.02.2018 № 13-ФЗ, от 08.08.2024 № 241-ФЗ)\n\nвлечет наложение административного штрафа в размере до пятикратной стоимости похищенного имущества, но не менее одной тысячи рублей, либо административный арест на срок до пятнадцати суток, либо обязательные работы на срок до пятидесяти часов.\n\nвлечет наложение административного штрафа в размере до пятикратной стоимости похищенного имущества, но не менее трех тысяч рублей, либо административный арест на срок от десяти до пятнадцати суток, либо обязательные работы на срок до ста двадцати часов.\n\nвлекут наложение административного штрафа на граждан в размере до пятикратной стоимости похищенного имущества, но не менее трех тысяч рублей с конфискацией орудий совершения административного правонарушения и (или) предмета административного правонарушения, либо административный арест на срок от десяти до пятнадцати суток с конфискацией орудий совершения административного правонарушения и (или) предмета административного правонарушения, либо обязательные работы на срок до ста двадцати часов с конфискацией орудий совершения административного правонарушения и (или) предмета административного правонарушения; на юридических лиц - от двадцати тысяч до пятидесяти тысяч рублей с конфискацией орудий совершения административного правонарушения и (или) предмета административного правонарушения.\n\n(Дополнение частью - Федеральный закон от 30.12.2021 № 468-ФЗ)\n\n(Статья в редакции Федерального закона от 03.07.2016 № 326-ФЗ)","article_title":"Статья 7.27. Мелкое хищение","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8643696a881f370b5155350542a2cde71de9d66d34fb5c7850aa98f725265893"},{"code_id":"KoAP_RF","article_number":"7.271","version_date":"2001-12-30","article_text":"Причинение имущественного ущерба собственнику или иному владельцу имущества путем обмана или злоупотребления доверием при отсутствии признаков уголовно наказуемого деяния -\n\nвлечет наложение административного штрафа в размере до пятикратной стоимости причиненного ущерба, но не менее пяти тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 07.12.2011 № 420-ФЗ)","article_title":"Статья 7.271. Причинение имущественного ущерба путем обмана или злоупотребления доверием","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"897dba33f6a38bc7517903a47ae60810601ab6a7fb59bb3740a94cc6be123bac"},{"code_id":"KoAP_RF","article_number":"7.28","version_date":"2001-12-30","article_text":"Нарушение установленного порядка патентования объектов промышленной собственности в иностранных государствах -\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи до двух тысяч рублей; на юридических лиц - от пятидесяти тысяч до восьмидесяти тысяч рублей.  (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 7.28. Нарушение установленного порядка патентования объектов промышленной собственности в иностранных государствах","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"35aa4ecd9fd2ed6b67f86e1698d5876d8af2e53807c058f0a0160f21d21848fc"},{"code_id":"KoAP_RF","article_number":"7.29","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 02.02.2006 № 19-ФЗ) (Утратила силу  - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.29. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"da6ccf924f54342660a92ae7e8f8b1d601cf6a69b1f18e010c535e8f89764307"},{"code_id":"KoAP_RF","article_number":"7.291","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 02.12.2013 № 326-ФЗ) (Утратила силу  - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.291. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5ada1748afda6042d5df18810cbd8a40bcdd36b0c68359e6571596a322363084"},{"code_id":"KoAP_RF","article_number":"7.292","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 02.12.2013 № 326-ФЗ) (Утратила силу  - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.292. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5ada1748afda6042d5df18810cbd8a40bcdd36b0c68359e6571596a322363084"},{"code_id":"KoAP_RF","article_number":"7.293","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 03.07.2016 № 318-ФЗ) (Утратила силу  - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.293. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2af79c3eb9c8705bb6ee187c038bec5fb81bc407551d2d9c8393109df6bc9012"},{"code_id":"KoAP_RF","article_number":"7.3","version_date":"2001-12-30","article_text":"(Наименование в редакции федеральных законов от 09.03.2021 № 38-ФЗ, от 25.12.2023 № 638-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от трех тысяч до пяти тысяч рублей; на должностных лиц - от тридцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от восьмисот тысяч до одного миллиона рублей.\n\nвлечет наложение административного штрафа на граждан в размере от двух тысяч до трех тысяч рублей; на должностных лиц - от двадцати тысяч до сорока тысяч рублей; на юридических лиц - от трехсот тысяч до пятисот тысяч рублей.\n\n(Статья в редакции Федерального закона от 28.12.2009 № 380-ФЗ)","article_title":"Статья 7.3. Пользование недрами без лицензии на пользование недрами либо нарушение условий, предусмотренных лицензией на пользование недрами, и (или) требований утвержденных в установленном порядке технических проектов, а также планов и схем развития горных работ","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"720fe8239de28c5e48a2258e603cefc9d4fff8edd8c0823fe86c3d6f50e70038"},{"code_id":"KoAP_RF","article_number":"7.30","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 02.02.2006 № 19-ФЗ) (Утратила силу  - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.30. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"da6ccf924f54342660a92ae7e8f8b1d601cf6a69b1f18e010c535e8f89764307"},{"code_id":"KoAP_RF","article_number":"7.301","version_date":"2001-12-30","article_text":"1. Нарушение установленных законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд (далее - законодательство Российской Федерации и иные нормативные правовые акты о контрактной системе в сфере закупок) порядка формирования, утверждения планов-графиков закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд (далее в настоящей статье - закупка) и внесения изменений в такие планы-графики или порядка размещения планов-графиков закупок в единой информационной системе в сфере закупок либо неразмещение плана-графика закупок в установленном законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок порядке -\n\nвлечет предупреждение или наложение административного штрафа на должностных лиц в размере от пяти тысяч до десяти тысяч рублей.\n\n2. Нарушение требований к закупаемым товарам, работам, услугам и (или) нормативных затрат, установленных в соответствии с законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок при нормировании в сфере закупок, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от десяти тысяч до двадцати тысяч рублей.\n\n3. Нарушение установленных в соответствии с законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок требований к определению и обоснованию начальной (максимальной) цены контракта, цены контракта, заключаемого с единственным поставщиком (подрядчиком, исполнителем), начальной цены единицы товара, работы, услуги или начальной суммы цен единиц товара, работы, услуги -\n\nвлечет наложение административного штрафа на должностных лиц в размере 1 процента начальной (максимальной) цены контракта, цены контракта, заключаемого с единственным поставщиком (подрядчиком, исполнителем), начальной цены единицы товара, работы, услуги, начальной суммы цен единиц товара, работы, услуги, но не менее десяти тысяч и не более пятидесяти тысяч рублей.\n\n4. Выбор способа определения поставщика (подрядчика, исполнителя) с нарушением требований, установленных законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок, либо применение закрытого конкурентного способа определения поставщика (подрядчика, исполнителя) без согласования с федеральным органом исполнительной власти, уполномоченным Правительством Российской Федерации, либо проведение закрытого конкурентного способа определения поставщика (подрядчика, исполнителя) на условиях, отличных от согласованных с указанным органом, либо заключение контракта с единственным поставщиком (подрядчиком, исполнителем) в случаях, не предусмотренных законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок, либо заключение контракта с единственным поставщиком (подрядчиком, исполнителем) без согласования с контрольным органом в сфере закупок в случаях, если необходимость такого согласования предусмотрена указанными законодательством и нормативными правовыми актами, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей.\n\n5. Нарушение установленных законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок требований к содержанию документов, формируемых (составляемых) при осуществлении закупок, к порядку и сроку размещения информации и документов, за исключением случаев, предусмотренных частями 1, 2 и 9 настоящей статьи, либо неразмещение информации и документов в нарушение порядка, установленного законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок, за исключением случаев, предусмотренных частями 1 и 9 настоящей статьи, -\n\nвлечет предупреждение или наложение административного штрафа на должностных лиц в размере от трех тысяч до десяти тысяч рублей.\n\n6. Действия, предусмотренные частью 5 настоящей статьи, повлекшие необоснованное ограничение количества участников закупки, -\n\nвлекут наложение административного штрафа на должностных лиц в размере 1 процента начальной (максимальной) цены контракта, но не менее десяти тысяч и не более пятидесяти тысяч рублей.\n\n7. Нарушение установленных законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок требований к рассмотрению и оценке заявки на участие в закупке, либо отклонение заявки на участие в закупке или отстранение участника закупки от участия в определении поставщика (подрядчика, исполнителя) в нарушение установленных указанными законодательством и нормативными правовыми актами требований, либо признание заявки соответствующей установленным при осуществлении закупки требованиям в случае, если такая заявка подлежит отклонению, -\n\nвлечет предупреждение или наложение административного штрафа на должностных лиц в размере 1 процента начальной (максимальной) цены контракта, но не менее пяти тысяч и не более тридцати тысяч рублей.\n\n8. Нарушение установленных законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок требований к порядку либо сроку возврата денежных средств, внесенных в качестве обеспечения заявки на участие в закупке или обеспечения исполнения контракта, за исключением случая, предусмотренного частью 4 статьи 7.306 настоящего Кодекса, -\n\nвлечет наложение административного штрафа на должностных лиц в размере 1 процента суммы денежных средств, внесенных в качестве обеспечения заявки или обеспечения исполнения контракта, но не менее пяти тысяч и не более тридцати тысяч рублей.\n\n9. Нарушение заказчиком, оператором электронной площадки, оператором специализированной площадки, кредитной организацией установленных законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок требований к порядку либо сроку размещения информации и документов или направления их для размещения в реестрах, предусмотренных указанными законодательством и нормативными правовыми актами, либо неразмещение информации и документов или ненаправление их для размещения в реестрах, предусмотренных указанными законодательством и нормативными правовыми актами, -\n\nвлечет предупреждение или наложение административного штрафа на должностных лиц в размере от десяти тысяч до двадцати тысяч рублей; на юридических лиц, являющихся кредитными организациями, - от тридцати тысяч до пятидесяти тысяч рублей.\n\n10. Включение заведомо недостоверной информации в реестр недобросовестных поставщиков (подрядчиков, исполнителей) -\n\nвлечет наложение административного штрафа на должностных лиц органа, осуществляющего ведение реестра недобросовестных поставщиков (подрядчиков, исполнителей), в размере от тридцати тысяч до пятидесяти тысяч рублей.\n\n11. Осуществление закупок у субъектов малого предпринимательства, социально ориентированных некоммерческих организаций в объеме менее объема, предусмотренного законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от сорока тысяч до шестидесяти тысяч рублей.\n\nПримечания:\n\n1. Если в соответствии с законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок при осуществлении закупки устанавливается максимальное значение цены контракта, размер административного штрафа, исчисляемого в соответствии с настоящей статьей исходя из размера начальной (максимальной) цены контракта, исчисляется от размера максимального значения цены контракта.\n\n2. Административная ответственность, установленная частью 7 настоящей статьи, не применяется, если требование, послужившее основанием для неправомерных рассмотрения и оценки заявки на участие в закупке, неправомерного отклонения заявки на участие в закупке, неправомерного отстранения участника закупки от участия в определении поставщика (подрядчика, исполнителя), неправомерного признания заявки соответствующей установленным при осуществлении закупки требованиям, установлено в извещении об осуществлении закупки, приглашении принять участие в определении поставщика (подрядчика, исполнителя), документации о закупке с нарушением законодательства Российской Федерации и иных нормативных правовых актов о контрактной системе в сфере закупок.\n\n3. Временем совершения административного правонарушения, предусмотренного частью 11 настоящей статьи, является дата окончания календарного года.\n\n(Дополнение статьей - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.301. Нарушение установленного законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд порядка планирования таких закупок и определения поставщика (подрядчика, исполнителя), требований к порядку, сроку размещения информации и документов или направления их для размещения в реестрах, предусмотренных указанными законодательством и нормативными правовыми актами","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ccffbc540faa2dfa7820d642ff568d5cdcf183ae0c159a85ce411a90a52a2a12"},{"code_id":"KoAP_RF","article_number":"7.302","version_date":"2001-12-30","article_text":"1. Заключение контракта по результатам определения поставщика (подрядчика, исполнителя) с нарушением условий, предусмотренных извещением об осуществлении закупки товаров, работ, услуг для обеспечения государственных и муниципальных нужд (далее в настоящей статье - закупка), приглашением принять участие в определении поставщика (подрядчика, исполнителя), документацией о закупке либо заявкой участника закупки (включая предварительное предложение о поставке товара), с которым заключен контракт, -\n\nвлечет наложение административного штрафа на должностных лиц в размере 1 процента начальной (максимальной) цены контракта, но не менее пяти тысяч и не более тридцати тысяч рублей; на юридических лиц - в размере 1 процента начальной (максимальной) цены контракта, но не менее пятидесяти тысяч и не более двухсот тысяч рублей.\n\n2. Нарушение установленных законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок требований к направлению или размещению проекта контракта, рассмотрению протокола разногласий, заключению контракта либо срокам осуществления таких действий -\n\nвлечет наложение административного штрафа на должностных лиц в размере от пяти тысяч до тридцати тысяч рублей.\n\n3. Изменение условий контракта, если возможность изменения таких условий контракта не предусмотрена законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от десяти тысяч до пятидесяти тысяч рублей; на юридических лиц - от ста тысяч до трехсот тысяч рублей.\n\n4. Действия, предусмотренные частями 1 и 3 настоящей статьи, повлекшие увеличение цены контракта, дополнительное расходование средств соответствующих бюджетов бюджетной системы Российской Федерации или уменьшение количества поставляемых товаров, объема выполняемых работ, оказываемых услуг, -\n\nвлекут наложение административного штрафа на должностных лиц в размере 1 процента цены контракта, но не менее пятидесяти тысяч и не более двухсот тысяч рублей; на юридических лиц - в размере 1 процента цены контракта, но не менее двухсот тысяч и не более четырехсот тысяч рублей.\n\n5. Несоблюдение требования о проведении экспертизы поставленного товара, результатов выполненной работы, оказанной услуги или отдельных этапов исполнения контракта в случае, если в соответствии с законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок к проведению такой экспертизы заказчик обязан привлечь экспертов, экспертные организации, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от пяти тысяч до двадцати тысяч рублей.\n\n6. Нарушение установленных законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок требований к оформлению приемки результатов отдельного этапа исполнения контракта, поставленного товара, выполненной работы (ее результатов) или оказанной услуги либо сроков такой приемки, ненаправление мотивированного отказа от подписания документа о приемке или неприменение мер ответственности к поставщику (подрядчику, исполнителю) в случае нарушения им условий контракта -\n\nвлечет наложение административного штрафа на должностных лиц в размере от десяти тысяч до двадцати тысяч рублей.\n\n7. Приемка результатов отдельного этапа исполнения контракта, поставленного товара, выполненной работы (ее результатов) или оказанной услуги при несоответствии поставленного товара, выполненной работы (ее результатов) или оказанной услуги условиям контракта в случаях, не предусмотренных законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок, -\n\nвлечет наложение административного штрафа на должностных лиц в размере 1 процента цены контракта, но не менее пятидесяти тысяч и не более двухсот тысяч рублей.\n\n8. Нарушение срока либо порядка оплаты отдельных этапов исполнения контракта, поставляемого товара, выполняемой работы (ее результатов) или оказываемой услуги, в том числе неисполнение обязанности по обеспечению авансирования, предусмотренного контрактом, -\n\nвлечет наложение административного штрафа на должностных лиц в размере 1 процента цены контракта (этапа исполнения контракта, аванса, предусмотренного контрактом), но не менее десяти тысяч и не более пятидесяти тысяч рублей.\n\n9. Нарушение установленного законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок порядка расторжения контракта в случае одностороннего отказа от исполнения контракта -\n\nвлечет предупреждение или наложение административного штрафа на должностных лиц в размере от десяти тысяч до пятидесяти тысяч рублей; на юридических лиц - от ста тысяч до двухсот тысяч рублей.\n\n10. Повторное совершение должностным лицом административного правонарушения, предусмотренного частью 4, 7 или 8 настоящей статьи, -\n\nвлечет дисквалификацию на срок от одного года до двух лет.\n\n(Дополнение статьей - Федеральный закон от 28.12.2024 № 500-ФЗ)\n\nатья 7.303. Нарушение порядка формирования, размещения и выполнения государственного оборонного заказа\n\n1. Нарушение установленного законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок порядка определения начальной (максимальной) цены государственного контракта при размещении государственного оборонного заказа путем использования конкурентных способов определения поставщиков (исполнителей, подрядчиков) или цены государственного контракта в случае размещения государственного оборонного заказа у единственного поставщика (исполнителя, подрядчика) -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей.\n\n2. Отказ или уклонение поставщика российских вооружения и военной техники, которые не имеют российских аналогов, единственного поставщика (исполнителя, подрядчика), определенного законодательными актами Российской Федерации, актами Президента Российской Федерации, актами Правительства Российской Федерации, от заключения государственного контракта по государственному оборонному заказу, если заключение такого государственного контракта является обязательным для указанных лиц, за исключением случаев, предусмотренных частью 3 настоящей статьи, статьей 14.31 настоящего Кодекса, если эти действия не содержат признаков уголовно наказуемого деяния, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от трехсот тысяч до одного миллиона рублей.\n\n3. Отказ или уклонение поставщика (исполнителя, подрядчика), занимающего в соответствии с законодательством Российской Федерации в сфере государственного оборонного заказа доминирующее положение, от заключения договора, необходимого для выполнения государственного оборонного заказа, если заключение такого договора является обязательным для указанного лица, если эти действия не содержат признаков уголовно наказуемого деяния, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от трехсот тысяч до одного миллиона рублей.\n\n4. Нарушение сроков размещения заказов на поставки товаров, выполнение работ, оказание услуг по государственному оборонному заказу, установленных Правительством Российской Федерации в соответствии с законодательством Российской Федерации в сфере государственного оборонного заказа, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей.\n\n5. Нарушение должностным лицом государственного заказчика условий государственного контракта по государственному оборонному заказу, за исключением случаев, предусмотренных частью 8 статьи 7.302 настоящего Кодекса, либо нарушение должностным лицом военного представительства государственного заказчика предусмотренных государственным контрактом по государственному оборонному заказу или контрактом порядка и (или) сроков осуществления контроля качества или приемки военной продукции, если эти действия не содержат признаков уголовно наказуемого деяния, -\n\nвлечет наложение административного штрафа в размере от тридцати тысяч до пятидесяти тысяч рублей.\n\n6. Нарушение должностным лицом головного исполнителя поставок продукции по государственному оборонному заказу (далее в настоящей статье - головной исполнитель) условий государственного контракта по государственному оборонному заказу, касающихся количества, качества, комплектности поставляемых товаров, качества выполняемых работ, оказываемых услуг, сроков поставки товаров, выполнения работ, оказания услуг, либо нарушение должностным лицом исполнителя, участвующего в поставках продукции по государственному оборонному заказу (далее в настоящей статье - исполнитель), условий контракта, касающихся количества, качества, комплектности поставляемых товаров, качества выполняемых работ, оказываемых услуг, сроков поставки товаров, выполнения работ, оказания услуг, если эти действия не содержат признаков уголовно наказуемого деяния, -\n\nвлечет наложение административного штрафа в размере от тридцати тысяч до пятидесяти тысяч рублей.\n\n7. Нарушение должностным лицом головного исполнителя срока и (или) порядка оплаты товаров (работ, услуг), поставляемых (выполняемых, оказываемых) по государственному оборонному заказу, в том числе неисполнение обязанности по обеспечению авансирования, если эти действия не содержат признаков уголовно наказуемого деяния, -\n\nвлечет наложение административного штрафа в размере от пятидесяти тысяч до ста тысяч рублей.\n\n8. Совершение головным исполнителем, исполнителем действий (бездействие), запрещенных законодательством Российской Федерации в сфере государственного оборонного заказа, если такие действия (бездействие) приводят или могут привести к необоснованному завышению цены на продукцию по государственному оборонному заказу, неисполнению или ненадлежащему исполнению государственного контракта по государственному оборонному заказу или контракта, за исключением случаев, предусмотренных частями 6, 7 и 9 настоящей статьи, статьей 14.31 настоящего Кодекса, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от трехсот тысяч до одного миллиона рублей.\n\n9. Включение головным исполнителем, исполнителем в себестоимость производства (реализации) продукции по государственному оборонному заказу затрат, не связанных с ее производством (реализацией), повлекшее получение излишнего дохода в размере более одного миллиона рублей, за исключением случаев, предусмотренных статьей 14.31 настоящего Кодекса, -\n\nвлечет наложение административного штрафа на должностных лиц в размере пятидесяти тысяч рублей; на юридических лиц - от трех миллионов до пяти миллионов рублей.\n\n10. Неисполнение уполномоченным банком установленных законодательством Российской Федерации в сфере государственного оборонного заказа обязанностей при осуществлении банковского сопровождения сопровождаемой сделки, за исключением случаев, предусмотренных частью 14 настоящей статьи, -\n\nвлечет предупреждение или наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей.\n\n11. Неисполнение головным исполнителем, исполнителем по государственному оборонному заказу требования о ведении раздельного учета результатов финансово-хозяйственной деятельности либо нарушение правил ведения такого учета -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от трехсот тысяч до пятисот тысяч рублей.\n\n12. Нарушение изготовителем (лицом, выполняющим функции иностранного изготовителя), поставщиком (подрядчиком, исполнителем) обязательных требований в отношении оборонной продукции (выполняемых работ, оказываемых услуг), поставляемой по государственному оборонному заказу, продукции (выполняемых работ, оказываемых услуг), используемой в целях защиты сведений, составляющих государственную тайну или относимых к охраняемой в соответствии с законодательством Российской Федерации иной информации ограниченного доступа, продукции (выполняемых работ, оказываемых услуг), сведения о которой составляют государственную тайну, продукции (выполняемых работ, оказываемых услуг) и объектов, связанных с обеспечением ядерной и радиационной безопасности в области использования атомной энергии, процессов проектирования (включая изыскания), производства, строительства, монтажа, наладки, эксплуатации, хранения, перевозки, реализации, утилизации, захоронения, связанных с обязательными требованиями в отношении указанной продукции и объектов, установленными в соответствии с законодательством Российской Федерации о техническом регулировании и законодательством Российской Федерации о стандартизации, в том числе государственными заказчиками, федеральными органами исполнительной власти, уполномоченными в области обеспечения безопасности, обороны, внешней разведки, противодействия техническим разведкам и технической защиты информации, государственного управления использованием атомной энергии, государственного регулирования безопасности при использовании атомной энергии, и (или) государственными контрактами (договорами), -\n\nвлечет наложение административного штрафа на должностных лиц в размере от сорока тысяч до пятидесяти тысяч рублей; на юридических лиц - от семисот тысяч до одного миллиона рублей.\n\n13. Ликвидация или перепрофилирование головным исполнителем без согласования с государственным заказчиком производственных мощностей, обеспечивающих поставки продукции по государственному оборонному заказу, в случае прекращения поставок такой продукции на очередной год и плановый период -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от трехсот тысяч до одного миллиона рублей.\n\n14. Совершение уполномоченным банком операций по счету, открытому головному исполнителю, исполнителю для осуществления расчетов по государственному оборонному заказу, проведение которых по такому счету не допускается в соответствии с законодательством Российской Федерации в сфере государственного оборонного заказа, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от ста тысяч до одного миллиона рублей.\n\n15. Непредставление или несвоевременное представление головным исполнителем или лицом, для которого в соответствии с законодательством Российской Федерации в сфере государственного оборонного заказа принятие государственного оборонного заказа обязательно, по запросу государственного заказчика либо непредставление или несвоевременное представление исполнителем или лицом, для которого в соответствии с законодательством Российской Федерации в сфере государственного оборонного заказа заключение контракта обязательно, по запросу головного исполнителя предложения о цене на продукцию по государственному оборонному заказу (в том числе обосновывающих такую цену документов) либо информации, подлежащей представлению в соответствии с законодательством Российской Федерации в сфере государственного оборонного заказа, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от трехсот тысяч до пятисот тысяч рублей.\n\n16. Нарушение головным исполнителем, исполнителем по государственному оборонному заказу установленных в соответствии с законодательством Российской Федерации в сфере государственного оборонного заказа сроков и (или) порядка представления отчета об исполнении государственного контракта, контракта, представление которого государственному заказчику является обязательным в соответствии с законодательством Российской Федерации в сфере государственного оборонного заказа, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от ста тысяч до трехсот тысяч рублей.\n\nПримечание. Излишним доходом, указанным в части 9 настоящей статьи, признается доход, определяемый как разница между доходом, полученным в результате незаконных действий, предусмотренных указанной частью, и доходом, который сформировался бы без таких незаконных действий.\n\n(Дополнение статьей - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.302. Нарушение порядка заключения, исполнения, изменения и расторжения контракта","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"90702fccc28b17b5711a85757650b3bee9012a9ba77665e2ad45ef19756c2e89"},{"code_id":"KoAP_RF","article_number":"7.304","version_date":"2001-12-30","article_text":"1. Осуществление закупки товаров, работ, услуг (далее в настоящей статье - закупка), если закупка в соответствии с законодательством Российской Федерации в сфере закупок товаров, работ, услуг отдельными видами юридических лиц (далее - законодательство Российской Федерации в сфере закупок отдельными видами юридических лиц) должна осуществляться в порядке, предусмотренном законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок, в ином порядке -\n\nвлечет наложение административного штрафа на должностных лиц в размере от пяти тысяч до тридцати тысяч рублей; на юридических лиц - от пятидесяти тысяч до ста тысяч рублей.\n\n2. Нарушение заказчиком установленных законодательством Российской Федерации в сфере закупок отдельными видами юридических лиц требований к содержанию документов, формируемых (составляемых) при осуществлении закупок, либо нарушение предусмотренных указанным законодательством порядка и сроков размещения информации и документов -\n\nвлечет предупреждение или наложение административного штрафа на должностных лиц в размере от трех тысяч до десяти тысяч рублей; на юридических лиц - от десяти тысяч до тридцати тысяч рублей.\n\n3. Установление требований к участникам закупок, к закупаемым товарам, работам, услугам и (или) к условиям договора с нарушением законодательства Российской Федерации в сфере закупок отдельными видами юридических лиц либо оценка и (или) сопоставление заявок на участие в закупке с нарушением требований, предусмотренных указанным законодательством, -\n\nвлекут предупреждение или наложение административного штрафа на должностных лиц в размере от пяти тысяч до тридцати тысяч рублей; на юридических лиц - от десяти тысяч до тридцати тысяч рублей.\n\n4. Нарушение установленных законодательством Российской Федерации в сфере закупок отдельными видами юридических лиц требований к порядку либо сроку размещения информации и документов или направления их для размещения в реестрах, предусмотренных указанным законодательством, -\n\nвлечет предупреждение или наложение административного штрафа на должностных лиц в размере от десяти тысяч до двадцати тысяч рублей; на юридических лиц - от тридцати тысяч до пятидесяти тысяч рублей.\n\n5. Нарушение заказчиком установленных законодательством Российской Федерации в сфере закупок отдельными видами юридических лиц сроков заключения договора либо нарушение порядка заключения договора по результатам конкурентной закупки в электронной форме, участниками которой могут быть только субъекты малого и среднего предпринимательства, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от пяти тысяч до тридцати тысяч рублей; на юридических лиц - от тридцати тысяч до пятидесяти тысяч рублей.\n\n6. Осуществление закупок у субъектов малого и среднего предпринимательства в размере менее размера, предусмотренного законодательством Российской Федерации в сфере закупок отдельными видами юридических лиц, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от пятидесяти тысяч до ста тысяч рублей.\n\n7. Нарушение установленного законодательством Российской Федерации в сфере закупок отдельными видами юридических лиц срока оплаты товаров, работ, услуг по договору (отдельному этапу договора), заключенному по результатам закупки с субъектом малого или среднего предпринимательства, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от пятидесяти тысяч до ста тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.304. Нарушение порядка осуществления закупок товаров, работ, услуг отдельными видами юридических лиц","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57dc7dda6a875eacf93c0d405a84e68ec7aac925af9fc0e88bdaa2b6cf46495a"},{"code_id":"KoAP_RF","article_number":"7.305","version_date":"2001-12-30","article_text":"1. Нарушение установленных законодательством Российской Федерации требований к порядку и (или) сроку размещения информации о проведении обязательных в соответствии с законодательством Российской Федерации торгов (далее - обязательные торги), продаже государственного или муниципального имущества и (или) размещение недостоверной информации о проведении обязательных торгов, продаже государственного или муниципального имущества, за исключением случаев, предусмотренных частями 1, 5 и 9 статьи 7.301, частями 2 и 4 статьи 7.304 настоящего Кодекса, либо предоставление документации, содержащей недостоверные сведения, -\n\nвлекут наложение административного штрафа на должностных лиц в размере от тридцати тысяч до сорока тысяч рублей; на индивидуальных предпринимателей - от сорока тысяч до пятидесяти тысяч рублей; на юридических лиц - от пятидесяти тысяч до ста тысяч рублей.\n\n2. Нарушение порядка определения формы проведения обязательных торгов, за исключением случаев, предусмотренных частью 4 статьи 7.301, частью 1 статьи 7.304 настоящего Кодекса, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до сорока тысяч рублей; на индивидуальных предпринимателей - от сорока тысяч до пятидесяти тысяч рублей; на юридических лиц - от пятидесяти тысяч до ста тысяч рублей.\n\n3. Нарушение порядка предоставления документации об обязательных торгах, порядка разъяснения такой документации, порядка приема заявок на участие в обязательных торгах, заявок на участие в продаже государственного или муниципального имущества, порядка допуска к участию в обязательных торгах или порядка определения победителя обязательных торгов, продажи государственного или муниципального имущества, за исключением случаев, предусмотренных частями 5 - 7 статьи 7.301, частями 2 и 3 статьи 7.304 настоящего Кодекса, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до тридцати тысяч рублей; на индивидуальных предпринимателей - от тридцати тысяч до сорока тысяч рублей; на юридических лиц - от сорока тысяч до пятидесяти тысяч рублей.\n\n4. Нарушение сроков заключения договоров по результатам проведения обязательных торгов, продажи государственного или муниципального имущества или в случае, если обязательные торги признаны несостоявшимися, либо уклонение организатора обязательных торгов, продавца государственного или муниципального имущества, организатора продажи государственного или муниципального имущества от заключения такого договора, за исключением случаев, предусмотренных частью 2 статьи 7.302, частью 5 статьи 7.304 настоящего Кодекса, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до сорока тысяч рублей; на юридических лиц - от тридцати тысяч до пятидесяти тысяч рублей.\n\n5. Изменение организатором обязательных торгов, продавцом государственного или муниципального имущества либо лицом, являющимся стороной договора, по соглашению сторон или в одностороннем порядке условий договора при его заключении или исполнении, установленных в документации об обязательных торгах, извещении о проведении обязательных торгов, информационном сообщении о продаже государственного или муниципального имущества, проектах договоров, в случае, если федеральным законом предусмотрен запрет такого изменения, за исключением случаев, предусмотренных частями 1, 3 и 4 статьи 7.302, частью 5 статьи 7.304, частью 1 статьи 7.306 настоящего Кодекса, -\n\nвлечет наложение административного штрафа на граждан в размере от двух тысяч до трех тысяч рублей; на должностных лиц - от двадцати тысяч до тридцати тысяч рублей; на юридических лиц - от пятидесяти тысяч до трехсот тысяч рублей.\n\n6. Нарушение процедуры и (или) порядка организации и проведения обязательных торгов, продажи государственного или муниципального имущества, за исключением случаев, предусмотренных частями 1 - 5 настоящей статьи, статьями 7.301 - 7.304, 7.306 настоящего Кодекса, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от трех тысяч до десяти тысяч рублей; на юридических лиц - от двадцати тысяч до тридцати тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.305. Нарушение процедуры обязательных в соответствии с законодательством Российской Федерации торгов, продажи государственного или муниципального имущества","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7b1fa14bebc6ca6a80f225e6ced29bf2874866f6bca164e31675b200950f3dfa"},{"code_id":"KoAP_RF","article_number":"7.306","version_date":"2001-12-30","article_text":"ния закупок, предусмотренных законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок, закупок, предусмотренных законодательством Российской Федерации в сфере закупок отдельными видами юридических лиц, и обязательных торгов в электронной форме, нарушение кредитной организацией установленного порядка блокирования и прекращения блокирования денежных средств на банковском счете участника таких закупок и (или) обязательных торгов\n\n1. Нарушение оператором электронной площадки, оператором специализированной электронной площадки установленных законодательством Российской Федерации правил документооборота при проведении закупок, предусмотренных законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок, закупок, предусмотренных законодательством Российской Федерации в сфере закупок отдельными видами юридических лиц (далее в настоящей статье - закупки), и обязательных торгов в электронной форме, за исключением случаев, предусмотренных частями 2 - 4 настоящей статьи, -\n\nвлечет наложение административного штрафа в размере от пяти тысяч до тридцати тысяч рублей.\n\n2. Нарушение оператором электронной площадки, оператором специализированной электронной площадки установленных законодательством Российской Федерации требований к обеспечению непрерывности проведения закупок и обязательных торгов в электронной форме, надежности функционирования программно-аппаратных средств, используемых для их проведения, равного доступа участников закупок и обязательных торгов к участию в них, неизменности подписанных усиленной квалифицированной электронной подписью документов -\n\nвлечет наложение административного штрафа в размере от ста тысяч до двухсот тысяч рублей.\n\n3. Нарушение оператором электронной площадки, оператором специализированной электронной площадки установленных законодательством Российской Федерации требований к обеспечению конфиденциальности информации при проведении закупок и обязательных торгов -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от двухсот тысяч до трехсот тысяч рублей.\n\n4. Нарушение кредитной организацией установленных законодательством Российской Федерации требований к порядку и (или) сроку блокирования и прекращения блокирования денежных средств на банковском счете участника закупок и (или) обязательных торгов либо нарушение оператором электронной площадки, оператором специализированной электронной площадки установленных законодательством Российской Федерации требований к порядку и (или) сроку направления в кредитную организацию информации, необходимой для осуществления таких блокирования и прекращения блокирования, -\n\nвлечет предупреждение или наложение административного штрафа в размере 1 процента суммы денежных средств, подлежащих блокированию или прекращению блокирования, но не менее пяти тысяч и не более тридцати тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.306. Нарушение оператором электронной площадки, оператором специализированной электронной площадки установленных порядков проведе","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0677c2cb323c42cb04d3fe30ac2246df31fa5242951f85eb4fab548bbdc843c2"},{"code_id":"KoAP_RF","article_number":"7.31","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 02.02.2006 № 19-ФЗ) (Утратила силу  - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.31. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"da6ccf924f54342660a92ae7e8f8b1d601cf6a69b1f18e010c535e8f89764307"},{"code_id":"KoAP_RF","article_number":"7.311","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 17.07.2009 № 160-ФЗ) (Утратила силу  - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.311. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b4157495ad2c00312ae1f76e7097aeabcdc051b772d1e5841ba96d108a8a532d"},{"code_id":"KoAP_RF","article_number":"7.32","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 02.02.2006 № 19-ФЗ) (Утратила силу  - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.32. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"da6ccf924f54342660a92ae7e8f8b1d601cf6a69b1f18e010c535e8f89764307"},{"code_id":"KoAP_RF","article_number":"7.321","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 02.12.2013 № 326-ФЗ) (Утратила силу  - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.321. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5ada1748afda6042d5df18810cbd8a40bcdd36b0c68359e6571596a322363084"},{"code_id":"KoAP_RF","article_number":"7.322","version_date":"2001-12-30","article_text":"Нарушение наймодателями по договорам найма жилых помещений жилищного фонда социального использования установленных жилищным законодательством обязательных требований к заключению и исполнению таких договоров, требований к деятельности по предоставлению жилых помещений по договорам найма жилых помещений жилищного фонда социального использования либо требований, установленных в отношении количества жилых помещений и общей площади жилых помещений, которые должны быть предоставлены в наемном доме социального использования по договорам найма жилых помещений жилищного фонда социального использования, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати до пятидесяти тысяч рублей; на юридических лиц - от ста до двухсот тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 21.07.2014 № 217-ФЗ)","article_title":"Статья 7.322. Нарушение требований жилищного законодательства к заключению и исполнению договоров найма жилых помещений жилищного фонда социального использования","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a06bd0b7a273c3898d0d21a15b51ffdc8c79c41a53640626d86aca0b7180c9d4"},{"code_id":"KoAP_RF","article_number":"7.323","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 05.05.2014 № 122-ФЗ) (Утратила силу  - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.323. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"927c6d10ad024d7078a195ea6f1002b381221584e9b9628e86819acb22b131c8"},{"code_id":"KoAP_RF","article_number":"7.324","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 05.10.2015 № 275-ФЗ) (Утратила силу  - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.324. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"96a0e068537607ca862019fbefaa402c8d233173028c9c1de46d335585f4c261"},{"code_id":"KoAP_RF","article_number":"7.325","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 26.07.2017 № 189-ФЗ) (Утратила силу  - Федеральный закон от 28.12.2024 № 500-ФЗ)","article_title":"Статья 7.325. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dea0fa3e7e613ab4982a63495c44102965f86fa704f443d0b3aad0c8290c0963"},{"code_id":"KoAP_RF","article_number":"7.326","version_date":"2001-12-30","article_text":"Дача экспертом, экспертной организацией, уполномоченным представителем экспертной организации заведомо ложного экспертного заключения в сфере закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд, если это действие не содержит уголовно наказуемого деяния, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей или дисквалификацию на срок от шести месяцев до одного года; на юридических лиц - от ста тысяч до ста пятидесяти тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 27.12.2018 № 510-ФЗ)","article_title":"Статья 7.326. Заведомо ложное экспертное заключение в сфере закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"45c8531fd043ffcd37db63f33bcb41730cf015f35145f0121d199de8dc7d7f15"},{"code_id":"KoAP_RF","article_number":"7.33","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 23.07.2013 № 245-ФЗ)\n\nУклонение исполнителя земляных, строительных, мелиоративных, хозяйственных или иных работ либо археологических полевых работ, осуществляемых на основании разрешения (открытого листа), от обязательной передачи государству в соответствии с законодательством Российской Федерации культурных ценностей, обнаруженных в результате проведения таких работ, если это действие не содержит уголовно наказуемого деяния, -   (В редакции Федерального закона от 23.07.2013 № 245-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи пятисот до двух тысяч пятисот рублей; на должностных лиц - от трех тысяч до четырех тысяч рублей; на юридических лиц - от тридцати тысяч до сорока тысяч рублей.  (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 26.07.2006 № 133-ФЗ)","article_title":"Статья 7.33. Уклонение исполнителя земляных, строительных, мелиоративных, хозяйственных или иных работ либо археологических полевых работ, осуществляемых на основании разрешения (открытого листа), от обязательной передачи государству культурных ценностей, обнаруженных в результате проведения таких работ","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"25f6e1e928c30ad5d9aa3dd1539cade8683e1bd11cb985a69941db752b1ad367"},{"code_id":"KoAP_RF","article_number":"7.34","version_date":"2001-12-30","article_text":"Использование земельного участка на праве постоянного (бессрочного) пользования юридическим лицом, не выполнившим в установленный федеральным законом срок обязанности по переоформлению такого права на право аренды земельного участка или по приобретению этого земельного участка в собственность, -\n\nвлечет наложение административного штрафа в размере от двадцати тысяч до ста тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 24.07.2007 № 212-ФЗ) (В редакции Федерального закона от 08.03.2015 № 46-ФЗ)","article_title":"Статья 7.34. Использование земельного участка на праве постоянного (бессрочного) пользования юридическим лицом, не выполнившим в установленный федеральным законом срок обязанности по переоформлению такого права на право аренды земельного участка или по приобретению этого земельного участка в собственность","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"17a4a1f4d246d3f04d703be93591d84a5633590a6e7fb14e13a6c147a21ad021"},{"code_id":"KoAP_RF","article_number":"7.35","version_date":"2001-12-30","article_text":"Нарушение государственным (муниципальным) унитарным предприятием или государственным (муниципальным) учреждением порядка согласования при совершении сделки по распоряжению государственным (муниципальным) имуществом -\n\nвлечет наложение административного штрафа на должностных лиц в размере от 1 до 10 процентов цены совершенной сделки или дисквалификацию на срок от шести месяцев до трех лет; на юридических лиц - от 10 до 20 процентов цены совершенной сделки.\n\n(Дополнение статьей - Федеральный закон от 28.11.2015 № 344-ФЗ)\n\n(Наименование в редакции Федерального закона от 13.06.2023 № 230-ФЗ)","article_title":"Статья 7.35. Нарушение порядка согласования при совершении сделки по распоряжению государственным (муниципальным) имуществом","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"43924f63a664378d54617e11a6d6ab770092bb77dc6b73089c3d62be49612c61"},{"code_id":"KoAP_RF","article_number":"7.4","version_date":"2001-12-30","article_text":"Застройка площадей залегания полезных ископаемых, в том числе размещение в местах их залегания подземных сооружений без разрешения, необеспечение сохранности зданий, сооружений, а также особо охраняемых территорий и объектов окружающей среды при пользовании недрами -\n\nвлечет наложение административного штрафа на граждан в размере от двух тысяч до трех тысяч рублей; на должностных лиц - от двадцати тысяч до тридцати тысяч рублей; на юридических лиц - от ста тысяч до двухсот тысяч рублей.\n\n(Статья в редакции Федерального закона от 28.12.2009 № 380-ФЗ)","article_title":"Статья 7.4. Самовольная застройка площадей залегания полезных ископаемых","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e938854a8d79ba4d61d2bb5ee7236750b1451a6e448388bf36de5a8508480cd3"},{"code_id":"KoAP_RF","article_number":"7.5","version_date":"2001-12-30","article_text":"Самовольная добыча янтаря, нефрита или иных полудрагоценных камней, либо транспортировка или хранение в целях сбыта незаконно добытых янтаря, нефрита или иных полудрагоценных камней в натуральном или переработанном виде, либо сбыт незаконно добытых янтаря, нефрита или иных полудрагоценных камней в натуральном или переработанном виде, если такие действия не содержат уголовно наказуемого деяния, -\n\nвлечет наложение административного штрафа на граждан в размере от двухсот тысяч до пятисот тысяч рублей с конфискацией орудия совершения административного правонарушения либо без таковой; на должностных лиц - от пятисот тысяч до восьмисот тысяч рублей с конфискацией орудия совершения административного правонарушения либо без таковой; на юридических лиц - от десяти миллионов до шестидесяти миллионов рублей с конфискацией орудия совершения административного правонарушения либо без таковой.\n\nПримечание. Перечень полудрагоценных камней в целях настоящей статьи устанавливается Правительством Российской Федерации.\n\n(Статья в редакции Федерального закона от 20.12.2017 № 414-ФЗ)","article_title":"Статья 7.5. Самовольная добыча янтаря, нефрита или иных полудрагоценных камней","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c0066c857e38a3671167b67a8546a0c9f4e8d2a208258e7627adf8363825c306"},{"code_id":"KoAP_RF","article_number":"7.6","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 03.06.2006 № 73-ФЗ)\n\nСамовольное занятие водного объекта или его части, либо использование их без документов, на основании которых возникает право пользования водным объектом или его частью, либо водопользование с нарушением его условий -  (В редакции Федерального закона от 03.06.2006 № 73-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи до трех тысяч рублей; на должностных лиц - от десяти тысяч до тридцати тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от десяти тысяч до тридцати тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от пятидесяти тысяч до ста тысяч рублей или административное приостановление деятельности на срок до девяноста суток. (В редакции Федерального закона от 21.10.2013 № 275-ФЗ)","article_title":"Статья 7.6. Самовольное занятие водного объекта или пользование им с нарушением установленных условий","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"35dbec7e1752c1968b4be9d90c50391031db2c49022a93cdfc4312a76fb47932"},{"code_id":"KoAP_RF","article_number":"7.7","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 14.07.2008 № 118-ФЗ)\n\nПовреждение объектов и систем водоснабжения, водоотведения, гидротехнических сооружений, устройств и установок водохозяйственного и водоохранного назначения -  (В редакции Федерального закона от 14.07.2008 № 118-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи до одной тысячи пятисот рублей; на должностных лиц - от двух тысяч до трех тысяч рублей; на юридических лиц - от двадцати тысяч до тридцати тысяч рублей.  (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 7.7. Повреждение объектов и систем водоснабжения, водоотведения, гидротехнических сооружений, устройств и установок водохозяйственного и водоохранного назначения","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ecb1729af3f404c148641e45b3f6bd60536c8d7a451a56cfebad9982ad570233"},{"code_id":"KoAP_RF","article_number":"7.8","version_date":"2001-12-30","article_text":"(Статья утратила силу - Федеральный закон от 28.12.2009 № 380-ФЗ)","article_title":"Статья 7.8. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7689ee01a0f30e103ab666160c8cf8f00ee1207250f6aab3a495996723dc7614"},{"code_id":"KoAP_RF","article_number":"7.9","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 04.12.2006 № 201-ФЗ)\n\nСамовольное занятие лесных участков или использование указанных участков для раскорчевки, переработки лесных ресурсов, устройства складов, возведения построек (строительства), распашки и других целей без специальных разрешений на использование указанных участков -  (В редакции Федерального закона от 04.12.2006 № 201-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от двадцати тысяч до пятидесяти тысяч рублей; на должностных лиц - от пятидесяти тысяч до ста тысяч рублей; на юридических лиц - от двухсот тысяч до трехсот тысяч рублей.  (В редакции Федерального закона от 08.03.2015 № 46-ФЗ)","article_title":"Статья 7.9. Самовольное занятие лесных участков","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4e1261c487e0d215142bd239a3be11929dfec5fe94cfdd7e06eb25eb0209ef6b"},{"code_id":"KoAP_RF","article_number":"8.1","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 28.12.2009 № 380-ФЗ)\n\nНесоблюдение экологических требований при территориальном планировании, градостроительном зонировании, планировке территории, архитектурно-строительном проектировании, строительстве, капитальном ремонте, реконструкции, вводе в эксплуатацию, эксплуатации, выводе из эксплуатации зданий, строений, сооружений и иных объектов капитального строительства, за исключением случаев, предусмотренных статьей 8.48 настоящего Кодекса, - (В редакции федеральных законов от 28.12.2009 № 380-ФЗ, от 27.12.2019 № 504-ФЗ)\n\nвлечет предупреждение или наложение административного штрафа на граждан в размере от одной тысячи до двух тысяч рублей; на должностных лиц - от двух тысяч до пяти тысяч рублей; на юридических лиц - от двадцати тысяч до ста тысяч рублей.  (В редакции федеральных законов от 26.12.2005 № 183-ФЗ; от 22.06.2007 № 116-ФЗ; от 27.07.2010 № 239-ФЗ)","article_title":"Статья 8.1. Несоблюдение экологических требований при осуществлении градостроительной деятельности и эксплуатации предприятий, сооружений или иных объектов","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cd73a0f0beb8898f812b5e7b4fcf38b9d24e640869de624c8901bd7f4f018491"},{"code_id":"KoAP_RF","article_number":"8.2","version_date":"2001-12-30","article_text":"влечет наложение административного штрафа на граждан в размере от двух тысяч до трех тысяч рублей; на должностных лиц - от десяти тысяч до тридцати тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от тридцати тысяч до пятидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от ста тысяч до двухсот пятидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток. (В редакции  Федерального закона от 14.07.2022 № 287-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от трех тысяч до пяти тысяч рублей; на должностных лиц - от тридцати тысяч до сорока тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от пятидесяти тысяч до семидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от двухсот пятидесяти тысяч до четырехсот тысяч рублей или административное приостановление деятельности на срок до девяноста суток. (В редакции  Федерального закона от 14.07.2022 № 287-ФЗ)\n\nвлекут наложение административного штрафа на граждан в размере от пяти тысяч до семи тысяч рублей; на должностных лиц - от сорока тысяч до пятидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от семидесяти тысяч до восьмидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от четырехсот тысяч до пятисот тысяч рублей или административное приостановление деятельности на срок до девяноста суток. (В редакции  Федерального закона от 14.07.2022 № 287-ФЗ)\n\nвлекут наложение административного штрафа на граждан в размере от десяти тысяч до пятнадцати тысяч рублей; на должностных лиц - от двадцати тысяч до тридцати тысяч рублей; на юридических лиц - от тридцати тысяч до пятидесяти тысяч рублей.\n\n(Дополнение частью - Федеральный закон от 14.07.2022 № 287-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от двадцати тысяч до тридцати тысяч рублей; на должностных лиц - от сорока тысяч до шестидесяти тысяч рублей с конфискацией транспортного средства, являющегося орудием совершения административного правонарушения, или без таковой; на юридических лиц - от шестидесяти тысяч до ста тысяч рублей с конфискацией транспортного средства, являющегося орудием совершения административного правонарушения, или без таковой.\n\n(Дополнение частью - Федеральный закон от 14.07.2022 № 287-ФЗ)\n\nвлекут наложение административного штрафа на граждан в размере от сорока тысяч до пятидесяти тысяч рублей; на должностных лиц - от шестидесяти тысяч до восьмидесяти тысяч рублей; на юридических лиц - от ста тысяч до ста двадцати тысяч рублей.\n\n(Дополнение частью - Федеральный закон от 14.07.2022 № 287-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от шестидесяти тысяч до семидесяти тысяч рублей; на должностных лиц - от восьмидесяти тысяч до ста тысяч рублей с конфискацией грузовых транспортных средств, прицепов к ним, тракторов и других самоходных машин, являющихся орудиями совершения административного правонарушения, или без таковой; на юридических лиц - от ста пятидесяти тысяч до двухсот тысяч рублей с конфискацией грузовых транспортных средств, прицепов к ним, тракторов и других самоходных машин, являющихся орудиями совершения административного правонарушения, или без таковой.\n\n(Дополнение частью - Федеральный закон от 14.07.2022 № 287-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от трех тысяч до пяти тысяч рублей; на должностных лиц - от двадцати тысяч до сорока тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от сорока тысяч до пятидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от трехсот тысяч до четырехсот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\nвлечет наложение административного штрафа на граждан в размере от пяти тысяч до шести тысяч рублей; на должностных лиц - от сорока тысяч до пятидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от пятидесяти тысяч до шестидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от пятисот тысяч до шестисот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\nвлекут наложение административного штрафа на граждан в размере от шести тысяч до семи тысяч рублей; на должностных лиц - от пятидесяти тысяч до шестидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от шестидесяти тысяч до семидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от шестисот тысяч до семисот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до сорока тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от сорока тысяч до шестидесяти тысяч рублей; на юридических лиц - от двухсот тысяч до трехсот пятидесяти тысяч рублей.\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до сорока тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от сорока тысяч до шестидесяти тысяч рублей; на юридических лиц - от двухсот тысяч до трехсот пятидесяти тысяч рублей.\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до сорока тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от сорока тысяч до шестидесяти тысяч рублей; на юридических лиц - от двухсот тысяч до трехсот пятидесяти тысяч рублей.\n\n10. Неисполнение обязанности по ведению учета в области обращения с отходами производства и потребления -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до сорока тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от сорока тысяч до шестидесяти тысяч рублей; на юридических лиц - от двухсот тысяч до трехсот пятидесяти тысяч рублей.\n\n11. Неисполнение обязанности по проведению мониторинга состояния и загрязнения окружающей среды на территориях объектов размещения отходов производства и потребления и в пределах их воздействия на окружающую среду -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до сорока тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования ю\n\nридического лица, - от сорока тысяч до шестидесяти тысяч рублей; на юридических лиц - от двухсот тысяч до трехсот пятидесяти тысяч рублей.\n\n12. Неисполнение обязанности по проведению инвентаризации объектов размещения отходов производства и потребления -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до сорока тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от сорока тысяч до шестидесяти тысяч рублей; на юридических лиц - от двухсот тысяч до трехсот пятидесяти тысяч рублей.\n\n13. Нарушение сроков или периодичности размещения информации в федеральной государственной информационной системе учета твердых коммунальных отходов либо размещение в указанной системе недостоверной информации или информации не в полном объеме, за исключением случаев, предусмотренных частью 14 настоящей статьи, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от трех тысяч до шести тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от пятидесяти тысяч до семидесяти тысяч рублей; на юридических лиц - от семидесяти тысяч до ста пятидесяти тысяч рублей.\n\n(Дополнение частью - Федеральный закон от 25.12.2023 № 668-ФЗ)\n\n14. Нарушение должностным лицом федерального органа исполнительной власти, органа исполнительной власти субъекта Российской Федерации, органа местного самоуправления сроков или периодичности размещения информации в федеральной государственной информационной системе учета твердых коммунальных отходов либо размещение в указанной системе недостоверной информации или информации не в полном объеме -\n\nвлечет наложение административного штрафа в размере от пяти тысяч до десяти тысяч рублей.\n\n(Дополнение частью - Федеральный закон от 25.12.2023 № 668-ФЗ)\n\n(Статья в редакции Федерального закона от 17.06.2019 № 141-ФЗ)","article_title":"Статья 8.2. Несоблюдение требований в области охраны окружающей среды при обращении с отходами производства и потребления","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"99a3cc8fc60b16b36f4e8ac5486790eaf2b21bd838fad87113a732ca2d064f94"},{"code_id":"KoAP_RF","article_number":"8.21","version_date":"2001-12-30","article_text":"1. Несоблюдение требований в области охраны окружающей среды при обращении с веществами, разрушающими озоновый слой, -\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи до двух тысяч рублей; на должностных лиц - от десяти тысяч до тридцати тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от тридцати тысяч до пятидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от ста тысяч до двухсот пятидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n2. Повторное в течение года совершение административного правонарушения, предусмотренного частью 1 настоящей статьи, -\n\nвлечет наложение административного штрафа на граждан в размере от двух тысяч пятисот до трех тысяч пятисот рублей; на должностных лиц - от тридцати тысяч до пятидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от пятидесяти тысяч до семидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от двухсот пятидесяти тысяч до четырехсот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n(Дополнение статьей - Федеральный закон от 17.06.2019 № 141-ФЗ)","article_title":"Статья 8.21. Несоблюдение требований в области охраны окружающей среды при обращении с веществами, разрушающими озоновый слой","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b2b3240a9d3b48f37f1f085b5add1c4a592889e0b6866404ffdfd17322eab83d"},{"code_id":"KoAP_RF","article_number":"8.22","version_date":"2001-12-30","article_text":"1. Несоблюдение требований в области охраны окружающей среды при производстве, обращении или обезвреживании потенциально опасных химических веществ, в том числе радиоактивных, иных веществ и микроорганизмов -\n\nвлечет наложение административного штрафа на граждан в размере от пяти тысяч до десяти тысяч рублей; на должностных лиц - от тридцати тысяч до пятидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от семидесяти тысяч до ста тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от ста тысяч до двухсот пятидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n2. Повторное в течение года совершение административного правонарушения, предусмотренного частью 1 настоящей статьи, -\n\nвлечет наложение административного штрафа на граждан в размере от десяти тысяч до двенадцати тысяч рублей; на должностных лиц - от пятидесяти тысяч до шестидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от ста тысяч до ста двадцати тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от двухсот пятидесяти тысяч до трехсот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n3. Действия (бездействие), предусмотренные частью 1 настоящей статьи, повлекшие причинение вреда здоровью людей или окружающей среде либо возникновение эпидемии или эпизоотии, если эти действия (бездействие) не содержат уголовно наказуемого деяния, -\n\nвлекут наложение административного штрафа на граждан в размере от пятнадцати тысяч до двадцати тысяч рублей; на должностных лиц - от шестидесяти тысяч до семидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от ста двадцати тысяч до ста сорока тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от трехсот пятидесяти тысяч до четырехсот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n(Дополнение статьей - Федеральный закон от 17.06.2019 № 141-ФЗ)","article_title":"Статья 8.22. Несоблюдение требований в области охраны окружающей среды при производстве, обращении или обезвреживании потенциально опасных химических веществ, в том числе радиоактивных, иных веществ и микроорганизмов","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9f04cf885447747304c696e2544f888a6afe880a147539cb961534a7c6ebcf2d"},{"code_id":"KoAP_RF","article_number":"8.23","version_date":"2001-12-30","article_text":"1. Несоблюдение требований в области охраны окружающей среды при сборе, накоплении, транспортировании, обработке, утилизации или обезвреживании отходов животноводства -\n\nвлечет наложение административного штрафа на граждан в размере от двух тысяч до трех тысяч рублей; на должностных лиц - от тридцати тысяч до сорока тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от пятидесяти тысяч до шестидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от двухсот пятидесяти тысяч до трехсот пятидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n2. Повторное в течение года совершение административного правонарушения, предусмотренного частью 1 настоящей статьи, -\n\nвлечет наложение административного штрафа на граждан в размере от трех тысяч до четырех тысяч рублей; на должностных лиц - от сорока тысяч до пятидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от шестидесяти тысяч до семидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от трехсот пятидесяти тысяч до четырехсот пятидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n3. Действия (бездействие), предусмотренные частью 1 настоящей статьи, повлекшие причинение вреда здоровью людей или окружающей среде либо возникновение эпидемии или эпизоотии, если эти действия (бездействие) не содержат уголовно наказуемого деяния, -\n\nвлекут наложение административного штрафа на граждан в размере от четырех тысяч до пяти тысяч рублей; на должностных лиц - от пятидесяти тысяч до шестидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от восьмидесяти тысяч до девяноста тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от пятисот тысяч до шестисот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n4. Несоблюдение требований в области охраны окружающей среды при размещении отходов животноводства -\n\nвлечет наложение административного штрафа на граждан в размере от пяти тысяч до семи тысяч рублей; на должностных лиц - от сорока тысяч до шестидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от шестидесяти тысяч до восьмидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от пятисот тысяч до семисот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n5. Повторное в течение года совершение административного правонарушения, предусмотренного частью 4 настоящей статьи, -\n\nвлечет наложение административного штрафа на граждан в размере от семи тысяч до восьми тысяч рублей; на должностных лиц - от шестидесяти тысяч до семидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от восьмидесяти тысяч до девяноста тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от семисот тысяч до восьмисот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n6. Действия (бездействие), предусмотренные частью 4 настоящей статьи, повлекшие причинение вреда здоровью людей или окружающей среде либо возникновение эпидемии или эпизоотии, если эти действия (бездействие) не содержат уголовно наказуемого деяния, -\n\nвлекут наложение административного штрафа на граждан в размере от восьми тысяч до девяти тысяч рублей; на должностных лиц - от семидесяти тысяч до восьмидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от девяноста тысяч до ста тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от восьмисот тысяч до девятисот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n(Дополнение статьей - Федеральный закон от 17.06.2019 № 141-ФЗ)","article_title":"Статья 8.23. Несоблюдение требований в области охраны окружающей среды при обращении с отходами животноводства","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"98fe3e4cdb70b650466c572dc3cc01a11586fc876aed2f79f40ec3ec1d0dfa1e"},{"code_id":"KoAP_RF","article_number":"8.3","version_date":"2001-12-30","article_text":"Нарушение правил испытаний, производства, транспортировки, хранения, применения и иного обращения с пестицидами и агрохимикатами (за исключением случаев, когда такие правила содержатся в технических регламентах), которое может повлечь причинение вреда окружающей среде, -   (В редакции федеральных законов от 30.12.2008 № 309-ФЗ; от 18.07.2011 № 237-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи до двух тысяч рублей; на должностных лиц - от двух тысяч до пяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от двух тысяч до пяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от десяти тысяч до ста тысяч рублей или административное приостановление деятельности на срок до девяноста суток.  (В редакции федеральных законов от 26.12.2005 № 183-ФЗ; от 22.06.2007 № 116-ФЗ)","article_title":"Статья 8.3. Нарушение правил обращения с пестицидами и агрохимикатами","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a993ccb929bdc2d1a32638fbbd1ab98ebf575ddbc531c9e720afcd0662ef9d8c"},{"code_id":"KoAP_RF","article_number":"8.4","version_date":"2001-12-30","article_text":"1. Невыполнение требований законодательства об обязательности проведения государственной экологической экспертизы, финансирование или реализация проектов, программ и иной документации, подлежащих государственной экологической экспертизе и не получивших положительного заключения государственной экологической экспертизы, -\n\nвлечет предупреждение или наложение административного штрафа на граждан в размере от одной тысячи пятисот до двух тысяч рублей; на должностных лиц - от десяти тысяч до двадцати тысяч рублей; на юридических лиц - от ста тысяч до двухсот пятидесяти тысяч рублей. (В редакции федеральных законов от 26.12.2005 № 183-ФЗ, от 22.06.2007 № 116-ФЗ, от 27.07.2010 № 239-ФЗ, от 17.06.2019 № 141-ФЗ)\n\n2. Осуществление деятельности, не соответствующей документации, которая получила положительное заключение государственной экологической экспертизы, -\n\nвлечет наложение административного штрафа на граждан в размере от двух тысяч до двух тысяч пятисот рублей; на должностных лиц - от десяти тысяч до двадцати тысяч рублей; на юридических лиц - от ста тысяч до двухсот пятидесяти тысяч рублей.  (В редакции федеральных законов от 26.12.2005 № 183-ФЗ, от 22.06.2007 № 116-ФЗ, от 17.06.2019 № 141-ФЗ)\n\n3. Незаконный отказ в государственной регистрации заявлений о проведении общественной экологической экспертизы -\n\nвлечет наложение административного штрафа на должностных лиц от пяти тысяч до десяти тысяч рублей.  (В редакции федеральных законов от 26.12.2005 № 183-ФЗ; от 22.06.2007 № 116-ФЗ)","article_title":"Статья 8.4. Нарушение законодательства об экологической экспертизе","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"78f1e0ac3a286892b4dea923d1240e064e14a274ae39ab6dd75348fb0ac33af8"},{"code_id":"KoAP_RF","article_number":"8.5","version_date":"2001-12-30","article_text":"1. Сокрытие, умышленное искажение или несвоевременное сообщение полной и достоверной информации о состоянии окружающей среды и природных ресурсов, об источниках загрязнения окружающей среды и природных ресурсов или иного вредного воздействия на окружающую среду и природные ресурсы, о радиационной обстановке, данных, полученных при осуществлении производственного экологического контроля, либо информации, содержащейся в заявлении о постановке на государственный учет объектов, оказывающих негативное воздействие на окружающую среду, или декларации о воздействии на окружающую среду, декларации о плате за негативное воздействие на окружающую среду, отчете о выполнении плана мероприятий по охране окружающей среды или программы повышения экологической эффективности, а равно искажение сведений о состоянии земель, водных объектов и других объектов окружающей среды лицами, обязанными сообщать такую информацию в соответствии с законодательством Российской Федерации, за исключением случаев, предусмотренных частями 13 и 14 статьи 8.2, статьями 8.52 и 8.53, частями 3 и 4 статьи 8.50, статьей 8.51 настоящего Кодекса, -\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи до трех тысяч рублей; на должностных лиц - от десяти тысяч до тридцати тысяч рублей; на юридических лиц - от пятидесяти тысяч до двухсот тысяч рублей.\n\n2. Повторное совершение административного правонарушения, предусмотренного частью 1 настоящей статьи, -\n\nвлечет наложение административного штрафа на граждан в размере от трех тысяч до пяти тысяч рублей; на должностных лиц - от тридцати тысяч до пятидесяти тысяч рублей или дисквалификацию на срок от одного года до трех лет; на юридических лиц - от двухсот тысяч до трехсот тысяч рублей.\n\n(Статья в редакции Федерального закона от 08.08.2024 № 242-ФЗ)","article_title":"Статья 8.5. Сокрытие или искажение экологической информации","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a2042f7c9983a990b73094301c1161c6a52852a44d703f82be9419c6da26e081"},{"code_id":"KoAP_RF","article_number":"8.51","version_date":"2001-12-30","article_text":"1. Непредставление или несвоевременное представление отчетности о выполнении нормативов утилизации отходов от использования товаров или деклараций о количестве выпущенных в обращение на территории Российской Федерации товаров, упаковки товаров, включенных в перечень товаров, упаковки товаров, подлежащих утилизации после утраты ими потребительских свойств, реализованных для внутреннего потребления на территории Российской Федерации за предыдущий календарный год, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от трех тысяч до шести тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от пятидесяти тысяч до семидесяти тысяч рублей; на юридических лиц - от семидесяти тысяч до ста пятидесяти тысяч рублей.\n\n2. Представление отчетности о выполнении нормативов утилизации отходов от использования товаров или деклараций о количестве выпущенных в обращение на территории Российской Федерации товаров, упаковки товаров, включенных в перечень товаров, упаковки товаров, подлежащих утилизации после утраты ими потребительских свойств, реализованных для внутреннего потребления на территории Российской Федерации за предыдущий календарный год, в неполном объеме либо отчетности, содержащей недостоверные сведения, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от трех тысяч до шести тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - в двукратном размере суммы сбора по каждой группе товаров, группе упаковки товаров, подлежащего уплате производителями товаров, импортерами товаров, которые не обеспечивают самостоятельную утилизацию отходов от использования товаров, но не менее ста тысяч рублей; на юридических лиц - в двукратном размере суммы сбора по каждой группе товаров, группе упаковки товаров, подлежащего уплате производителями товаров, импортерами товаров, которые не обеспечивают самостоятельную утилизацию отходов от использования товаров, но не менее двухсот пятидесяти тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 17.06.2019 № 141-ФЗ)","article_title":"Статья 8.51. Нарушение порядка представления отчетности о выполнении нормативов утилизации отходов от использования товаров или деклараций о количестве выпущенных в обращение на территории Российской Федерации товаров, упаковки товаров, включенных в перечень товаров, упаковки товаров, подлежащих утилизации после утраты ими потребительских свойств, реализованных для внутреннего потребления на территории Российской Федерации за предыдущий календарный год","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c9cd93e01f951527225900a6f636a0f7be6b48afd9bad3c4a60ee7f3af219b19"},{"code_id":"KoAP_RF","article_number":"8.52","version_date":"2001-12-30","article_text":"1. Ненаправление в установленный законом срок утвержденного акта лесопатологического обследования в уполномоченный федеральный орган исполнительной власти -\n\nвлечет наложение административного штрафа на должностных лиц в размере от пяти тысяч до двадцати тысяч рублей.\n\n2. Включение недостоверных сведений о санитарном и лесопатологическом состоянии лесов в акт лесопатологического обследования либо размещение на официальном сайте органа государственной власти или органа местного самоуправления в информационно-телекоммуникационной сети \"Интернет\" утвержденного акта лесопатологического обследования, содержащего недостоверные сведения о санитарном и лесопатологическом состоянии лесов, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от пяти тысяч до двадцати тысяч рублей.\n\n3. Совершение административных правонарушений, предусмотренных частями 1 и 2 настоящей статьи, в отношении защитных лесов, особо защитных участков лесов, а также лесов, расположенных в лесопарковых зеленых поясах, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до сорока тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 06.06.2019 № 135-ФЗ)","article_title":"Статья 8.52. Сокрытие сведений о санитарном и лесопатологическом состоянии лесов или включение недостоверных сведений о санитарном и лесопатологическом состоянии лесов в акт лесопатологического обследования","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2eee2abea7903df304c7eceb0aa230a8d77495eb4ae65d38ae786e1376a3364c"},{"code_id":"KoAP_RF","article_number":"8.53","version_date":"2001-12-30","article_text":"Непредставление или несвоевременное представление информации для включения в федеральную государственную информационную систему учета и контроля за обращением с отходами I и II классов опасности, либо ее неразмещение или несвоевременное размещение в указанной системе, либо нарушение порядка представления такой информации, либо представление или размещение ее не в полном объеме, либо представление или размещение недостоверной информации -\n\nвлечет наложение административного штрафа на должностных лиц в размере от трех тысяч","article_title":"Статья 8.53. Нарушение порядка представления информации в федеральную государственную информационную систему учета и контроля за обращением с отходами I и II классов опасности либо порядка ее размещения в данной системе","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"77a9b802c79e4ec6eb613fdc6fa563bf6b22c7e91d17b7ee2164579686151c00"},{"code_id":"KONST_RF","article_number":"1","version_date":"1993-12-12","article_text":"1.Российская Федерация — Россия есть демократическое федеративное правовое государство с республиканской формой правления.\n\n2.Наименования Российская Федерация и Россия равнозначны.","article_title":"Статья 1","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a8c7380fd1d1fc0812fdee122ac9347237daeb46c97277e5f828d39bf327ac72"},{"code_id":"KONST_RF","article_number":"10","version_date":"1993-12-12","article_text":"Государственная власть в Российской Федерации осуществляется на основе разделения на законодательную, исполнительную и судебную. Органы законодательной, исполнительной и судебной власти самостоятельны.","article_title":"Статья 10","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"84c2b73a00a867db117cb9c24547d76c49a203bb1ac159cab59b8968a0f0e337"},{"code_id":"KONST_RF","article_number":"100","version_date":"1993-12-12","article_text":"1.Совет Федерации и Государственная Дума заседают раздельно.\n\n2.Заседания Совета Федерации и Государственной Думы являются открытыми. В случаях, предусмотренных регламентом палаты, она вправе проводить закрытые заседания.\n\n3.Палаты могут собираться совместно для заслушивания посланий Президента Российской Федерации.*","article_title":"Статья 100","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"11262768ce5f164ac50a53a5be1b800594f3cc881788412443d4dc0c8d0cd07a"},{"code_id":"KONST_RF","article_number":"101","version_date":"1993-12-12","article_text":"1.Совет Федерации избирает из своего состава Председателя Совета Федерации и его заместителей. Государственная Дума избирает из своего состава Председателя Государственной Думы и его заместителей.\n\n2.Председатель Совета Федерации и его заместители, Председатель Государственной Думы и его заместители ведут заседания и ведают внутренним распорядком палаты.\n\n3.Совет Федерации и Государственная Дума образуют комитеты и комиссии, проводят по вопросам своего ведения парламентские слушания.\n\n4.Каждая из палат принимает свой регламент и решает вопросы внутреннего распорядка своей деятельности.\n\n5.Для осуществления контроля за исполнением федерального бюджета Совет Федерации и Государственная Дума образуют Счетную палату, состав и порядок деятельности которой определяются федеральным законом.","article_title":"Статья 101","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dcfcb1e693d7450aec58fcc6f4a616dde26a5254de3d7cadfb0fd470de559a62"},{"code_id":"KONST_RF","article_number":"102","version_date":"1993-12-12","article_text":"1.К ведению Совета Федерации относятся:\n\nа)утверждение изменения границ между субъектами Российской Федерации;\n\nб)утверждение указа Президента Российской Федерации о введении военного положения;\n\nв)утверждение указа Президента Российской Федерации о введении чрезвычайного положения;\n\nг)решение вопроса о возможности использования Вооруженных Сил Российской Федерации за пределами территории Российской Федерации;\n\nд)назначение выборов Президента Российской Федерации;\n\nе)отрешение Президента Российской Федерации от должности; лишение неприкосновенности Президента Российской Федерации, прекратившего исполнение своих полномочий;*\n\nж)назначение на должность по представлению Президента Российской Федерации Председателя Конституционного Суда Российской Федерации, заместителя Председателя Конституционного Суда Российской Федерации и судей Конституционного Суда Российской Федерации, Председателя Верховного Суда Российской Федерации, заместителей Председателя Верховного Суда Российской Федерации и судей Верховного Суда Российской Федерации;*\n\nз)проведение консультаций по предложенным Президентом Российской Федерации кандидатурам на должность Генерального прокурора Российской Федерации, заместителей Генерального прокурора Российской Федерации, прокуроров субъектов Российской Федерации, прокуроров военных и других специализированных прокуратур, приравненных к прокурорам субъектов Российской Федерации;*\n\nи)назначение на должность и освобождение от должности Председателя Счетной палаты и половины от общего числа аудиторов Счетной палаты по представлению Президента Российской Федерации;*\n\nк)проведение консультаций по предложенным Президентом Российской Федерации кандидатурам на должность руководителей федеральных органов исполнительной власти (включая федеральных министров), ведающих вопросами обороны, безопасности государства, внутренних дел, юстиции, иностранных дел, предотвращения чрезвычайных ситуаций и ликвидации последствий стихийных бедствий, общественной безопасности;*\n\nл)прекращение по представлению Президента Российской Федерации в соответствии с федеральным конституционным законом полномочий Председателя Конституционного Суда Российской Федерации, заместителя Председателя Конституционного Суда Российской Федерации и судей Конституционного Суда Российской Федерации, Председателя Верховного Суда Российской Федерации, заместителей Председателя Верховного Суда Российской Федерации и судей Верховного Суда Российской Федерации, председателей, заместителей председателей и судей кассационных и апелляционных судов в случае совершения ими поступка, порочащего честь и достоинство судьи, а также в иных предусмотренных федеральным конституционным законом случаях, свидетельствующих о невозможности осуществления судьей своих полномочий;*\n\nм)заслушивание ежегодных докладов Генерального прокурора Российской Федерации о состоянии законности и правопорядка в Российской Федерации;*\n\n2.Совет Федерации принимает постановления по вопросам, отнесенным к его ведению Конституцией Российской Федерации.\n\n3.Постановления Совета Федерации принимаются большинством голосов от общего числа сенаторов Российской Федерации, если иной порядок принятия решений не предусмотрен Конституцией Российской Федерации.*","article_title":"Статья 102","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"25941e4070546a9ff0b3d368047b880048eae5bd0aa2c852a204be909eec2754"},{"code_id":"KONST_RF","article_number":"103","version_date":"1993-12-12","article_text":"1.К ведению Государственной Думы относятся:\n\nа)утверждение по представлению Президента Российской Федерации кандидатуры Председателя Правительства Российской Федерации;*\n\nа1)утверждение по представлению Председателя Правительства Российской Федерации кандидатур заместителей Председателя Правительства Российской Федерации и федеральных министров, за исключением федеральных министров, указанных в пункте «д1» статьи 83 Конституции Российской Федерации;*\n\nб)решение вопроса о доверии Правительству Российской Федерации;\n\nв)заслушивание ежегодных отчетов Правительства Российской Федерации о результатах его деятельности, в том числепо вопросам, поставленным Государственной Думой;\n\nЧасть 1 дополнена новым пунктом«в», буквенные обозначения последующих пунктов изменены в соответствии с Законом Российской Федерации о поправке к Конституции Российской Федерации от 30 декабря 2008 г. № 7-ФКЗ«О контрольных полномочиях Государственной Думы в отношении Правительства Российской Федерации», вступившим в силу со дня его официального опубликования 31 декабря 2008 г.(Российская газета, 2008, 31 декабря).\n\nг)назначение на должность и освобождение от должности Председателя Центрального банка Российской Федерации;\n\nг1)заслушивание ежегодных отчетов Центрального банка Российской Федерации;*\n\nд)назначение на должность и освобождение от должности заместителя Председателя Счетной палаты и половины от общего числа аудиторов Счетной палаты по представлению Президента Российской Федерации;*\n\nе)назначение на должность и освобождение от должности Уполномоченного по правам человека, действующего в соответствии с федеральным конституционным законом. Уполномоченным по правам человека может быть гражданин Российской Федерации, постоянно проживающий в Российской Федерации, не имеющий гражданства иностранного государства либо вида на жительство или иного документа, подтверждающего право на постоянное проживание гражданина Российской Федерации на территории иностранного государства. Уполномоченному по правам человека в порядке, установленном федеральным законом, запрещается открывать и иметь счета (вклады), хранить наличные денежные средства и ценности в иностранных банках, расположенных за пределами территории Российской Федерации;*\n\nж)объявление амнистии;\n\nз)выдвижение обвинения против Президента Российской Федерации в целях отрешения его от должности или против Президента Российской Федерации, прекратившего исполнение своих полномочий, в целях лишения его неприкосновенности.*\n\n2.Государственная Дума принимает постановления по вопросам, отнесенным к ее ведению Конституцией Российской Федерации.\n\n3.Постановления Государственной Думы принимаются большинством голосов от общего числа депутатов Государственной Думы, если иной порядок принятия решений не предусмотрен Конституцией Российской Федерации.","article_title":"Статья 103","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fbdc2463f42db62867ebcaa41646d2ddd01ea6377f075759ff7e3e56abd301bf"},{"code_id":"KONST_RF","article_number":"104","version_date":"1993-12-12","article_text":"1.Право законодательной инициативы принадлежит Президенту Российской Федерации, Совету Федерации, сенаторам Российской Федерации, депутатам Государственной Думы, Правительству Российской Федерации, законодательным (представительным) органам субъектов Российской Федерации. Право законодательной инициативы принадлежит также Конституционному Суду Российской Федерации и Верховному Суду Российской Федерации по вопросам их ведения.*\n\n2.Законопроекты вносятся в Государственную Думу.\n\n3.Законопроекты о введении или отмене налогов, освобождении от их уплаты, о выпуске государственных займов, об изменении финансовых обязательств государства, другие законопроекты, предусматривающие расходы, покрываемые за счет федерального бюджета, могут быть внесены только при наличии заключения Правительства Российской Федерации.","article_title":"Статья 104","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cd96abb0e4b833367c8db4238d89a5a7785ace6c570dfb46d8c3732e19a91d01"},{"code_id":"KONST_RF","article_number":"105","version_date":"1993-12-12","article_text":"1.Федеральные законы принимаются Государственной Думой.\n\n2.Федеральные законы принимаются большинством голосов от общего числа депутатов Государственной Думы, если иное не предусмотрено Конституцией Российской Федерации.\n\n3.Принятые Государственной Думой федеральные законы в течение пяти дней передаются на рассмотрение Совета Федерации.\n\n4.Федеральный закон считается одобренным Советом Федерации, если за него проголосовало более половины от общего числа членов этой палаты либо если в течение четырнадцати дней он не был рассмотрен Советом Федерации. В случае отклонения федерального закона Советом Федерации палаты могут создать согласительную комиссию для преодоления возникших разногласий, после чего федеральный закон подлежит повторному рассмотрению Государственной Думой.\n\n5.В случае несогласия Государственной Думы с решением Совета Федерации федеральный закон считается принятым, если при повторном голосовании за него проголосовало не менее двух третей от общего числа депутатов Государственной Думы.","article_title":"Статья 105","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ae752ec4a6077be5caa66f8a589a48315ad4ea68110f48cf0eb1cd997f84c225"},{"code_id":"KONST_RF","article_number":"106","version_date":"1993-12-12","article_text":"Обязательному рассмотрению в Совете Федерации подлежат принятые Государственной Думой федеральные законы по вопросам:\n\nа)федерального бюджета;\n\nб)федеральных налогов и сборов;\n\nв)финансового, валютного, кредитного, таможенного регулирования, денежной эмиссии;\n\nг)ратификации и денонсации международных договоров Российской Федерации;\n\nд)статуса и защиты государственной границы Российской Федерации;\n\nе)войны и мира.","article_title":"Статья 106","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"16d09d42d121c4b0ba004e66213d9bd279f727691064118c3bb8178951e36729"},{"code_id":"KONST_RF","article_number":"107","version_date":"1993-12-12","article_text":"1.Принятый федеральный закон в течение пяти дней направляется Президенту Российской Федерации для подписания и обнародования.\n\n2.Президент Российской Федерации в течение четырнадцати дней подписывает федеральный закон и обнародует его.\n\n3.Если Президент Российской Федерации в течение четырнадцати дней с момента поступления федерального закона отклонит его, то Государственная Дума и Совет Федерации в установленном Конституцией Российской Федерации порядке вновь рассматривают данный закон. Если при повторном рассмотрении федеральный закон будет одобрен в ранее принятой редакции большинством не менее двух третей голосов от общего числа сенаторов Российской Федерации и депутатов Государственной Думы, он подлежит подписанию Президентом Российской Федерации в течение семи дней и обнародованию. Если Президент Российской Федерации в течение указанного срока обратится в Конституционный Суд Российской Федерации с запросом о проверке конституционности федерального закона, срок для подписания такого закона приостанавливается на время рассмотрения запроса Конституционным Судом Российской Федерации. Если Конституционный Суд Российской Федерации подтвердит конституционность федерального закона, Президент Российской Федерации подписывает его в трехдневный срок с момента вынесения Конституционным Судом Российской Федерации соответствующего решения. Если Конституционный Суд Российской Федерации не подтвердит конституционности федерального закона, Президент Российской Федерации возвращает его в Государственную Думу без подписания.*","article_title":"Статья 107","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9fe37ed9e8756a6ef7f3b709139df6d86f9cacd83ce2004f2f04bde050bc7aad"},{"code_id":"KONST_RF","article_number":"108","version_date":"1993-12-12","article_text":"1.Федеральные конституционные законы принимаются по вопросам, предусмотренным Конституцией Российской Федерации.\n\n2.Федеральный конституционный закон считается принятым, если он одобрен большинством не менее трех четвертей голосов от общего числа сенаторов Российской Федерации и не менее двух третей голосов от общего числа депутатов Государственной Думы. Принятый федеральный конституционный закон в течение четырнадцати дней подлежит подписанию Президентом Российской Федерации и обнародованию. Если Президент Российской Федерации в течение указанного срока обратится в Конституционный Суд Российской Федерации с запросом о проверке конституционности федерального конституционного закона, срок для подписания такого закона приостанавливается на время рассмотрения запроса Конституционным Судом Российской Федерации. Если Конституционный Суд Российской Федерации подтвердит конституционность федерального конституционного закона, Президент Российской Федерации подписывает его в трехдневный срок с момента вынесения Конституционным Судом Российской Федерации соответствующего решения. Если Конституционный Суд Российской Федерации не подтвердит конституционности федерального конституционного закона, Президент Российской Федерации возвращает его в Государственную Думу без подписания.*","article_title":"Статья 108","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c6bbba00b7807cb81b41773e9743719de3d67aba85455c4b23e4aa8cb733cd89"},{"code_id":"KONST_RF","article_number":"109","version_date":"1993-12-12","article_text":"1.Государственная Дума может быть распущена Президентом Российской Федерации в случаях, предусмотренных статьями 111, 112 и 117 Конституции Российской Федерации.*\n\n2.В случае роспуска Государственной Думы Президент Российской Федерации назначает дату выборов с тем, чтобы вновь избранная Государственная Дума собралась не позднее чем через четыре месяца с момента роспуска.\n\n3.Государственная Дума не может быть распущена по основаниям, предусмотренным статьей 117 Конституции Российской Федерации, в течение года после ее избрания.\n\n4.Государственная Дума не может быть распущена с момента выдвижения ею обвинения против Президента Российской Федерации до принятия соответствующего решения Советом Федерации.\n\n5.Государственная Дума не может быть распущена в период действия на всей территории Российской Федерации военного или чрезвычайного положения, а также в течение шести месяцев до окончания срока полномочий Президента Российской Федерации.","article_title":"Статья 109","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2624671090fbb08d409de2d1fe60eb939e934c137946114c479241c46049e7c2"},{"code_id":"KONST_RF","article_number":"11","version_date":"1993-12-12","article_text":"1.Государственную власть в Российской Федерации осуществляют Президент Российской Федерации, Федеральное Собрание(Совет Федерации и Государственная Дума), Правительство Российской Федерации, суды Российской Федерации.\n\n2.Государственную власть в субъектах Российской Федерации осуществляют образуемые ими органы государственной власти.\n\n3.Разграничение предметов ведения и полномочий между органами государственной власти Российской Федерации и органами государственной власти субъектов Российской Федерации осуществляется настоящей Конституцией, Федеративным и иными договорами о разграничении предметов ведения и полномочий.","article_title":"Статья 11","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6898bd265c2cb5358dc8c1481d0b71b1b5193cc43f162a0a99b66a07fb074531"},{"code_id":"KONST_RF","article_number":"110","version_date":"1993-12-12","article_text":"1.Исполнительную власть Российской Федерации осуществляет Правительство Российской Федерации под общим руководством Президента Российской Федерации.*\n\n2.Правительство Российской Федерации состоит из Председателя Правительства Российской Федерации, заместителей Председателя Правительства Российской Федерации и федеральных министров.\n\n3.Правительство Российской Федерации руководит деятельностью федеральных органов исполнительной власти, за исключением федеральных органов исполнительной власти, руководство деятельностью которых осуществляет Президент Российской Федерации.*\n\n4.Председателем Правительства Российской Федерации, Заместителем Председателя Правительства Российской Федерации, федеральным министром, иным руководителем федерального органа исполнительной власти может быть гражданин Российской Федерации, достигший 30 лет, не имеющий гражданства иностранного государства либо вида на жительство или иного документа, подтверждающего право на постоянное проживание гражданина Российской Федерации на территории иностранного государства. Председателю Правительства Российской Федерации, заместителям Председателя Правительства Российской Федерации, федеральным министрам, иным руководителям федеральных органов исполнительной власти в порядке, установленном федеральным законом, запрещается открывать и иметь счета (вклады), хранить наличные денежные средства и ценности в иностранных банках, расположенных за пределами территории Российской Федерации.*","article_title":"Статья 110","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"abee031891374b3265dbb3f33eb26e42bdcee00cf222b34b8c54d5a5aab8cf0f"},{"code_id":"KONST_RF","article_number":"111","version_date":"1993-12-12","article_text":"1.Председатель Правительства Российской Федерации назначается Президентом Российской Федерации после утверждения его кандидатуры Государственной Думой.*\n\n2.Представление по кандидатуре Председателя Правительства Российской Федерации вносится в Государственную Думу Президентом Российской Федерации не позднее двухнедельного срока после вступления в должность вновь избранного Президента Российской Федерации или после отставки Правительства Российской Федерации либо в течение недели со дня отклонения кандидатуры Председателя Правительства Российской Федерации Государственной Думой или освобождения Президентом Российской Федерации от должности либо отставки Председателя Правительства Российской Федерации.*\n\n3.Государственная Дума рассматривает представленную Президентом Российской Федерации кандидатуру Председателя Правительства Российской Федерации в течение недели со дня внесения представления.*\n\n4.После трехкратного отклонения представленных кандидатур Председателя Правительства Российской Федерации Государственной Думой Президент Российской Федерации назначает Председателя Правительства Российской Федерации. В этом случае Президент Российской Федерации вправе распустить Государственную Думу и назначить новые выборы.*","article_title":"Статья 111","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8af5de5dd127d5469c5142a288ef35d7e5febedbc34820b1862ea5de08a59faa"},{"code_id":"KONST_RF","article_number":"112","version_date":"1993-12-12","article_text":"1.Председатель Правительства Российской Федерации не позднее недельного срока после назначения представляет Президенту Российской Федерации предложения о структуре федеральных органов исполнительной власти, за исключением случая, когда предшествующий Председатель Правительства Российской Федерации освобожден от должности Президентом Российской Федерации.\n\n2.Председатель Правительства Российской Федерации представляет Государственной Думе на утверждение кандидатуры заместителей Председателя Правительства Российской Федерации и федеральных министров (за исключением федеральных министров, указанных в пункте «д1» статьи 83 Конституции Российской Федерации). Государственная Дума не позднее недельного срока принимает решение по представленным кандидатурам.\n\n3.Заместители Председателя Правительства Российской Федерации и федеральные министры, кандидатуры которых утверждены Государственной Думой, назначаются на должность Президентом Российской Федерации. Президент Российской Федерации не вправе отказать в назначении на должность заместителей Председателя Правительства Российской Федерации и федеральных министров, кандидатуры которых утверждены Государственной Думой.\n\n4.После трехкратного отклонения Государственной Думой представленных в соответствии с частью 2 настоящей статьи кандидатур заместителей Председателя Правительства Российской Федерации, федеральных министров Президент Российской Федерации вправе назначить заместителей Председателя Правительства Российской Федерации, федеральных министров из числа кандидатур, представленных Председателем Правительства Российской Федерации. Если после трехкратного отклонения Государственной Думой представленных в соответствии с частью 2 настоящей статьи кандидатур более одной трети должностей членов Правительства Российской Федерации (за исключением должностей федеральных министров, указанных в пункте «д1» статьи 83 Конституции Российской Федерации) остаются вакантными, Президент Российской Федерации вправе распустить Государственную Думу и назначить новые выборы.\n\n5.В случае, предусмотренном частью 4 статьи 111 Конституции Российской Федерации, а также в случае роспуска Государственной Думы в соответствии с Конституцией Российской Федерации Президент Российской Федерации назначает заместителей Председателя Правительства Российской Федерации, федеральных министров (за исключением федеральных министров, указанных в пункте «д1» статьи 83 Конституции Российской Федерации) по представлению Председателя Правительства Российской Федерации.","article_title":"Статья 112","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e5160448394fb1d3ae5075fb0ad2cb2c19222f840b083ee66d5e67c9943bb3de"},{"code_id":"KONST_RF","article_number":"113","version_date":"1993-12-12","article_text":"Председатель Правительства Российской Федерации в соответствии с Конституцией Российской Федерации, федеральными законами, указами, распоряжениями, поручениями Президента Российской Федерации организует работу Правительства Российской Федерации. Председатель Правительства Российской Федерации несет персональную ответственность перед Президентом Российской Федерации за осуществление возложенных на Правительство Российской Федерации полномочий.","article_title":"Статья 113","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"00d4c7c95f004ebc0f05d268f8f7919ec49b3794e06fb368e137e588a2d94e65"},{"code_id":"KONST_RF","article_number":"114","version_date":"1993-12-12","article_text":"1.Правительство Российской Федерации:\n\nа)разрабатывает и представляет Государственной Думе федеральный бюджет и обеспечивает его исполнение; представляет Государственной Думе отчет об исполнении федерального бюджета; представляет Государственной Думе ежегодные отчеты о результатах своей деятельности, в том числепо вопросам, поставленным Государственной Думой;\n\nРедакция пункта«а» части 1 приведена в соответствии с Законом Российской Федерации о поправке к Конституции Российской Федерации от 30 декабря 2008 г. № 7-ФКЗ«О контрольных полномочиях Государственной Думы в отношении Правительства Российской Федерации», вступившим в силу со дня его официального опубликования 31 декабря 2008 г.(Российская газета, 2008, 31 декабря).\n\nб)обеспечивает проведение в Российской Федерации единой финансовой, кредитной и денежной политики;\n\nв)обеспечивает проведение в Российской Федерации единой социально ориентированной государственной политики в области культуры, науки, образования, здравоохранения, социального обеспечения, поддержки, укрепления и защиты семьи, сохранения традиционных семейных ценностей, а также в области охраны окружающей среды;*\n\nв1)обеспечивает государственную поддержку научно-технологического развития Российской Федерации, сохранение и развитие ее научного потенциала;*\n\nв2)обеспечивает функционирование системы социальной защиты инвалидов, основанной на полном и равном осуществлении ими прав и свобод человека и гражданина, их социальную интеграцию без какой-либо дискриминации, создание доступной среды для инвалидов и улучшение качества их жизни;*\n\nг)осуществляет управление федеральной собственностью;\n\nд)осуществляет меры по обеспечению обороны страны, государственной безопасности, реализации внешней политики Российской Федерации;\n\nе)осуществляет меры по обеспечению законности, прав и свобод граждан, охране собственности и общественного порядка, борьбе с преступностью;\n\nе1)осуществляет меры по поддержке институтов гражданского общества, в том числе некоммерческих организаций, обеспечивает их участие в выработке и проведении государственной политики;*\n\nе2)осуществляет меры по поддержке добровольческой (волонтерской) деятельности;*\n\nе3)содействует развитию предпринимательства и частной инициативы;*\n\nе4)обеспечивает реализацию принципов социального партнерства в сфере регулирования трудовых и иных непосредственно связанных с ними отношений;*\n\nе5)осуществляет меры, направленные на создание благоприятных условий жизнедеятельности населения, снижение негативного воздействия хозяйственной и иной деятельности на окружающую среду, сохранение уникального природного и биологического многообразия страны, формирование в обществе ответственного отношения к животным;*\n\nе6)создает условия для развития системы экологического образования граждан, воспитания экологической культуры;*\n\nж)осуществляет иные полномочия, возложенные на него Конституцией Российской Федерации, федеральными законами, указами Президента Российской Федерации.\n\n2.Порядок деятельности Правительства Российской Федерации определяется федеральным конституционным законом.","article_title":"Статья 114","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"10cb3ab24b52ec7289c775b8e20dabe5f38926bc0f84f185410d9dbf354d89c2"},{"code_id":"KONST_RF","article_number":"115","version_date":"1993-12-12","article_text":"1.На основании и во исполнение Конституции Российской Федерации, федеральных законов, указов, распоряжений, поручений Президента Российской Федерации Правительство Российской Федерации издает постановления и распоряжения, обеспечивает их исполнение.*\n\n2.Постановления и распоряжения Правительства Российской Федерации обязательны к исполнению в Российской Федерации.\n\n3.Постановления и распоряжения Правительства Российской Федерации в случае их противоречия Конституции Российской Федерации, федеральным законам, указам и распоряжениям Президента Российской Федерации могут быть отменены Президентом Российской Федерации.*","article_title":"Статья 115","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a4a90f4a6dc66ec4f1c7488aea716887ecd5f30a50c401ea4876a194c6194872"},{"code_id":"KONST_RF","article_number":"116","version_date":"1993-12-12","article_text":"Перед вновь избранным Президентом Российской Федерации Правительство Российской Федерации слагает свои полномочия.","article_title":"Статья 116","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"028e7808e14a8b68813e05b9501ed456b0701b4631b1c1bc7a10331c62e7df62"},{"code_id":"KONST_RF","article_number":"117","version_date":"1993-12-12","article_text":"1.Правительство Российской Федерации может подать в отставку, которая принимается или отклоняется Президентом Российской Федерации.\n\n2.Президент Российской Федерации может принять решение об отставке Правительства Российской Федерации.\n\n3.Государственная Дума может выразить недоверие Правительству Российской Федерации. Постановление о недоверии Правительству Российской Федерации принимается большинством голосов от общего числа депутатов Государственной Думы. После выражения Государственной Думой недоверия Правительству Российской Федерации Президент Российской Федерации вправе объявить об отставке Правительства Российской Федерации либо не согласиться с решением Государственной Думы. В случае если Государственная Дума в течение трех месяцев повторно выразит недоверие Правительству Российской Федерации, Президент Российской Федерации объявляет об отставке Правительства Российской Федерации либо распускает Государственную Думу и назначает новые выборы.*\n\n4.Председатель Правительства Российской Федерации вправе поставить перед Государственной Думой вопрос о доверии Правительству Российской Федерации, который подлежит рассмотрению в течение семи дней. Если Государственная Дума отказывает в доверии Правительству Российской Федерации, Президент Российской Федерации в течение семи дней вправе принять решение об отставке Правительства Российской Федерации или о роспуске Государственной Думы и назначении новых выборов. В случае если Правительство Российской Федерации в течение трех месяцев повторно поставит перед Государственной Думой вопрос о доверии, а Государственная Дума в доверии Правительству Российской Федерации откажет, Президент Российской Федерации принимает решение об отставке Правительства Российской Федерации или о роспуске Государственной Думы и назначении новых выборов.*\n\n41.Председатель Правительства Российской Федерации, Заместитель Председателя Правительства Российской Федерации, федеральный министр вправе подать в отставку, которая принимается или отклоняется Президентом Российской Федерации.*\n\n5.В случае отставки или сложения полномочий Правительство Российской Федерации по поручению Президента Российской Федерации продолжает действовать до сформирования нового Правительства Российской Федерации. В случае освобождения от должности Президентом Российской Федерации или отставки Председателя Правительства Российской Федерации, Заместителя Председателя Правительства Российской Федерации, федерального министра Президент Российской Федерации вправе поручить этому лицу продолжать исполнять обязанности по должности или возложить их исполнение на другое лицо до соответствующего назначения.*\n\n6.Государственная Дума не может выразить недоверие Правительству Российской Федерации, а Председатель Правительства Российской Федерации не может ставить перед Государственной Думой вопрос о доверии Правительству Российской Федерации в случаях, предусмотренных частями 3 — 5 статьи 109 Конституции Российской Федерации, а также в течение года после назначения Председателя Правительства Российской Федерации в соответствии с частью 4 статьи 111 Конституции Российской Федерации.*\n\nРедакция наименования главы  7 приведена в соответствии с Законом Российской Федерации о поправке к Конституции Российской Федерации от 5 февраля 2014 г. № 2-ФКЗ «О Верховном Суде Российской Федерации и прокуратуре Российской Федерации», вступившим в силу со дня его официального опубликования 6 февраля 2014 г. (Официальный интернет-портал правовой информации (www.pravo.gov.ru), 2014, 6 февраля, № 0001201402060001).","article_title":"Статья 117","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a1c6794a3280d65dfc0a7ff4eafe53bee5e9df540b2127e81f4861ce3f3f8c63"},{"code_id":"KONST_RF","article_number":"118","version_date":"1993-12-12","article_text":"1.Правосудие в Российской Федерации осуществляется только судом.\n\n2.Судебная власть осуществляется посредством конституционного, гражданского, арбитражного, административного и уголовного судопроизводства.*\n\n3.Судебная система Российской Федерации устанавливается Конституцией Российской Федерации и федеральным конституционным законом. Судебную систему Российской Федерации составляют Конституционный Суд Российской Федерации, Верховный Суд Российской Федерации, федеральные суды общей юрисдикции, арбитражные суды, мировые судьи субъектов Российской Федерации. Создание чрезвычайных судов не допускается.*","article_title":"Статья 118","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"113236f307f6b7d26fce398162e5db9bfa83fde44a5b6e11d532f0fefe112f7d"},{"code_id":"KONST_RF","article_number":"119","version_date":"1993-12-12","article_text":"Судьями могут быть граждане Российской Федерации, достигшие 25 лет, имеющие высшее юридическое образование и стаж работы по юридической профессии не менее пяти лет, постоянно проживающие в Российской Федерации, не имеющие гражданства иностранного государства либо вида на жительство или иного документа, подтверждающего право на постоянное проживание гражданина Российской Федерации на территории иностранного государства. Судьям судов Российской Федерации в порядке, установленном федеральным законом, запрещается открывать и иметь счета (вклады), хранить наличные денежные средства и ценности в иностранных банках, расположенных за пределами территории Российской Федерации. Федеральным законом могут быть установлены дополнительные требования к судьям судов Российской Федерации.","article_title":"Статья 119","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"042b71a7d9d9fa18aa84383ea92e192dbef3989bd5bbe07805d853cd0c1377d6"},{"code_id":"KONST_RF","article_number":"12","version_date":"1993-12-12","article_text":"В Российской Федерации признается и гарантируется местное самоуправление. Местное самоуправление в пределах своих полномочий самостоятельно. Органы местного самоуправления не входят в систему органов государственной власти.","article_title":"Статья 12","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"97f395e79a69ff62a7cda29c3b6c4ad8c27b9e006eff4f26c58ec99ddbef5f82"},{"code_id":"KONST_RF","article_number":"120","version_date":"1993-12-12","article_text":"1.Судьи независимы и подчиняются только Конституции Российской Федерации и федеральному закону.\n\n2.Суд, установив при рассмотрении дела несоответствие акта государственного или иного органа закону, принимает решение в соответствии с законом.","article_title":"Статья 120","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3b6b1d6fc5ba0c7b089d193825f3f50ec10829177059b406aaa4aef359e01d89"},{"code_id":"KONST_RF","article_number":"121","version_date":"1993-12-12","article_text":"1.Судьи несменяемы.\n\n2.Полномочия судьи могут быть прекращены или приостановлены не иначе как в порядке и по основаниям, установленным федеральным законом.","article_title":"Статья 121","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ce0f1e34cbe2a4cc561bc6ec9c1cf6badc9c0a3cfbfcc9bcc14a397768ecc598"},{"code_id":"KONST_RF","article_number":"122","version_date":"1993-12-12","article_text":"1.Судьи неприкосновенны.\n\n2.Судья не может быть привлечен к уголовной ответственности иначе как в порядке, определяемом федеральным законом.","article_title":"Статья 122","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c2439e4d8fcf6f420df14a130b635d71fed60a3e1d05bf113ea102fc4ba3167c"},{"code_id":"KONST_RF","article_number":"123","version_date":"1993-12-12","article_text":"1.Разбирательство дел во всех судах открытое. Слушание дела в закрытом заседании допускается в случаях, предусмотренных федеральным законом.\n\n2.Заочное разбирательство уголовных дел в судах не допускается, кроме случаев, предусмотренных федеральным законом.\n\n3.Судопроизводство осуществляется на основе состязательности и равноправия сторон.\n\n4.В случаях, предусмотренных федеральным законом, судопроизводство осуществляется с участием присяжных заседателей.","article_title":"Статья 123","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"006f6edcd3ecf06109c8d2cd065d693adb0452afa41c213638909d5550730d17"},{"code_id":"KONST_RF","article_number":"124","version_date":"1993-12-12","article_text":"Финансирование судов производится только из федерального бюджета и должно обеспечивать возможность полного и независимого осуществления правосудия в соответствии с федеральным законом.","article_title":"Статья 124","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f3250b62ff12d62e77a706ec2a2c48017e0df9e609b61987ed46e5f1facf544b"},{"code_id":"KONST_RF","article_number":"125","version_date":"1993-12-12","article_text":"1.Конституционный Суд Российской Федерации является высшим судебным органом конституционного контроля в Российской Федерации, осуществляющим судебную власть посредством конституционного судопроизводства в целях защиты основ конституционного строя, основных прав и свобод человека и гражданина, обеспечения верховенства и прямого действия Конституции Российской Федерации на всей территории Российской Федерации. Конституционный Суд Российской Федерации состоит из 11 судей, включая Председателя Конституционного Суда Российской Федерации и его заместителя.*\n\n2.Конституционный Суд Российской Федерации по запросам Президента Российской Федерации, Совета Федерации, Государственной Думы, одной пятой сенаторов Российской Федерации или депутатов Государственной Думы, Правительства Российской Федерации, Верховного Суда Российской Федерации, органов законодательной и исполнительной власти субъектов Российской Федерации разрешает дела о соответствии Конституции Российской Федерации:*\n\nа)федеральных конституционных законов, федеральных законов, нормативных актов Президента Российской Федерации, Совета Федерации, Государственной Думы, Правительства Российской Федерации;*\n\nб)конституций республик, уставов, а также законов и иных нормативных актов субъектов Российской Федерации, изданных по вопросам, относящимся к ведению органов государственной власти Российской Федерации и совместному ведению органов государственной власти Российской Федерации и органов государственной власти субъектов Российской Федерации;*\n\nв)договоров между органами государственной власти Российской Федерации и органами государственной власти субъектов Российской Федерации, договоров между органами государственной власти субъектов Российской Федерации;*\n\nг)не вступивших в силу международных договоров Российской Федерации.*\n\n3.Конституционный Суд Российской Федерации разрешает споры о компетенции:\n\nа)между федеральными органами государственной власти;\n\nб)между органами государственной власти Российской Федерации и органами государственной власти субъектов Российской Федерации;\n\nв)между высшими государственными органами субъектов Российской Федерации.\n\n4.Конституционный Суд Российской Федерации в порядке, установленном федеральным конституционным законом, проверяет:*\n\nа)по жалобам на нарушение конституционных прав и свобод граждан — конституционность законов и иных нормативных актов, указанных в пунктах «а» и «б» части 2 настоящей статьи, примененных в конкретном деле, если исчерпаны все другие внутригосударственные средства судебной защиты;*\n\nб)по запросам судов — конституционность законов и иных нормативных актов, указанных в пунктах «а» и «б» части 2 настоящей статьи, подлежащих применению в конкретном деле.*\n\n5.Конституционный Суд Российской Федерации по запросам Президента Российской Федерации, Совета Федерации, Государственной Думы, Правительства Российской Федерации, органов законодательной власти субъектов Российской Федерации дает толкование Конституции Российской Федерации.\n\n51.Конституционный Суд Российской Федерации:\n\nа)по запросу Президента Российской Федерации проверяет конституционность проектов законов Российской Федерации о поправке к Конституции Российской Федерации, проектов федеральных конституционных законов и федеральных законов, а также принятых в порядке, предусмотренном частями 2 и 3 статьи 107 и частью 2 статьи 108 Конституции Российской Федерации, законов до их подписания Президентом Российской Федерации;\n\nб)в порядке, установленном федеральным конституционным законом, разрешает вопрос о возможности исполнения решений межгосударственных органов, принятых на основании положений международных договоров Российской Федерации в их истолковании, противоречащем Конституции Российской Федерации, а также о возможности исполнения решения иностранного или  международного (межгосударственного) суда, иностранного или международного третейского суда (арбитража), налагающего обязанности на Российскую Федерацию, в случае если это решение противоречит основам публичного правопорядка Российской Федерации;\n\nв)по запросу Президента Российской Федерации в порядке, установленном федеральным конституционным законом, проверяет конституционность законов субъекта Российской Федерации до их обнародования высшим должностным лицом субъекта Российской Федерации (руководителем высшего исполнительного органа государственной власти субъекта Российской Федерации).*\n\n6.Акты или их отдельные положения, признанные неконституционными, утрачивают силу; не соответствующие Конституции Российской Федерации международные договоры Российской Федерации не подлежат введению в действие и применению. Акты или их отдельные положения, признанные конституционными в истолковании, данном Конституционным Судом Российской Федерации, не подлежат применению в ином истолковании.*\n\n7.Конституционный Суд Российской Федерации по запросу Совета Федерации дает заключение о соблюдении установленного порядка выдвижения обвинения Президента Российской Федерации либо Президента Российской Федерации, прекратившего исполнение своих полномочий, в государственной измене или совершении иного тяжкого преступления.*\n\n8.Конституционный Суд Российской Федерации осуществляет иные полномочия, установленные федеральным конституционным законом.*","article_title":"Статья 125","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8f4a5b83738ea985067e3cb92e756f3ed243a78d345b08b902e6f59357a9dc9b"},{"code_id":"KONST_RF","article_number":"126","version_date":"1993-12-12","article_text":"Верховный Суд Российской Федерации является высшим судебным органом по гражданским делам, разрешению экономических споров, уголовным, административным и иным делам, подсудным судам общей юрисдикции и арбитражным судам, образованным в соответствии с федеральным конституционным законом и осуществляющим судебную власть посредством гражданского, арбитражного, административного и уголовного судопроизводства. Верховный Суд Российской Федерации осуществляет в предусмотренных федеральным законом процессуальных формах судебный надзор за деятельностью судов общей юрисдикции и арбитражных судов и дает разъяснения по вопросам судебной практики.","article_title":"Статья 126","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"06a4a3232e7bb9b110dae4d1d4bc93357bee5c1b89747eadf0f5f93d0714ebbc"},{"code_id":"KONST_RF","article_number":"127","version_date":"1993-12-12","article_text":"Исключена поправкой к Конституции Российской Федерации (Закон Российской Федерации о поправке к Конституции Российской Федерации «О Верховном Суде Российской Федерации и прокуратуре Российской Федерации»).\n\nСтатья 127 исключена в соответствии с Законом Российской Федерации о поправке к Конституции Российской Федерации от 5 февраля 2014 г. № 2-ФКЗ «О Верховном Суде Российской Федерации и прокуратуре Российской Федерации», вступившим в силу со дня его официального опубликования 6 февраля 2014 г. (Официальный интернет-портал правовой информации (www.pravo.gov.ru), 2014, 6 февраля, № 0001201402060001).","article_title":"Статья 127","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"50e76b2b29be44151d83f48561bb3fbce6850496edfbb9c4c98b0ad24dbb9cc7"},{"code_id":"KONST_RF","article_number":"128","version_date":"1993-12-12","article_text":"1.Председатель Конституционного Суда Российской Федерации, заместитель Председателя Конституционного Суда Российской Федерации и судьи Конституционного Суда Российской Федерации, Председатель Верховного Суда Российской Федерации, заместители Председателя Верховного Суда Российской Федерации и судьи Верховного Суда Российской Федерации назначаются Советом Федерации по представлению Президента Российской Федерации.\n\n2.Председатели, заместители председателей и судьи других федеральных судов назначаются Президентом Российской Федерации в порядке, установленном федеральным конституционным законом.\n\n3.Полномочия, порядок образования и деятельности Конституционного Суда Российской Федерации, Верховного Суда Российской Федерации и иных федеральных судов устанавливаются Конституцией Российской Федерации и федеральным конституционным законом. Порядок осуществления гражданского, арбитражного, административного и уголовного судопроизводства регулируется также соответствующим процессуальным законодательством.","article_title":"Статья 128","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ee76b59a7ba7e4fc16f196fd0bd83ea8ce013023799badc5e382f72cf2be14f0"},{"code_id":"KONST_RF","article_number":"129","version_date":"1993-12-12","article_text":"1.Прокуратура Российской Федерации — единая федеральная централизованная система органов, осуществляющих надзор за соблюдением Конституции Российской Федерации и исполнением законов, надзор за соблюдением прав и свобод человека и гражданина, уголовное преследование в соответствии со своими полномочиями, а также выполняющих иные функции. Полномочия и функции прокуратуры Российской Федерации, ее организация и порядок деятельности определяются федеральным законом.\n\n2.Прокурорами могут быть граждане Российской Федерации, не имеющие гражданства иностранного государства либо вида на жительство или иного документа, подтверждающего право на постоянное проживание гражданина Российской Федерации на территории иностранного государства. Прокурорам в порядке, установленном федеральным законом, запрещается открывать и иметь счета (вклады), хранить наличные денежные средства и ценности в иностранных банках, расположенных за пределами территории Российской Федерации.\n\n3.Генеральный прокурор Российской Федерации, заместители Генерального прокурора Российской Федерации назначаются на должность после консультаций с Советом Федерации и освобождаются от должности Президентом Российской Федерации.\n\n4.Прокуроры субъектов Российской Федерации, прокуроры военных и других специализированных прокуратур, приравненные к прокурорам субъектов Российской Федерации, назначаются на должность после консультаций с Советом Федерации и освобождаются от должности Президентом Российской Федерации.\n\n5.Иные прокуроры могут назначаться на должность и освобождаться от должности Президентом Российской Федерации, если такой порядок назначения на должность и освобождения от должности установлен федеральным законом.\n\n6.Если иное не предусмотрено федеральным законом, прокуроры городов, районов и приравненные к ним прокуроры назначаются на должность и освобождаются от должности Генеральным прокурором Российской Федерации.","article_title":"Статья 129","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8cea44d4f644aaf96e98bca06bf58dc53b5bb296ce758581c64ce9c98d10206a"},{"code_id":"KONST_RF","article_number":"13","version_date":"1993-12-12","article_text":"1.В Российской Федерации признается идеологическое многообразие.\n\n2.Никакая идеология не может устанавливаться в качестве государственной или обязательной.\n\n3.В Российской Федерации признаются политическое многообразие, многопартийность.\n\n4.Общественные объединения равны перед законом.\n\n5.Запрещается создание и деятельность общественных объединений, цели или действия которых направлены на насильственное изменение основ конституционного строя и нарушение целостности Российской Федерации, подрыв безопасности государства, создание вооруженных формирований, разжигание социальной, расовой, национальной и религиозной розни.","article_title":"Статья 13","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0ec14e72812ddb770c91f66ef955068c5fe3af499736a53f4a7b010edae97d04"},{"code_id":"KONST_RF","article_number":"130","version_date":"1993-12-12","article_text":"1.Местное самоуправление в Российской Федерации обеспечивает самостоятельное решение населением вопросов местного значения, владение, пользование и распоряжение муниципальной собственностью.\n\n2.Местное самоуправление осуществляется гражданами путем референдума, выборов, других форм прямого волеизъявления, через выборные и другие органы местного самоуправления.","article_title":"Статья 130","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3685a95696b34374ddeb538affc046436a96152f4a1909649548968b23ab342c"},{"code_id":"KONST_RF","article_number":"131","version_date":"1993-12-12","article_text":"1.Местное самоуправление осуществляется в муниципальных образованиях, виды которых устанавливаются федеральным законом. Территории муниципальных образований определяются с учетом исторических и иных местных традиций. Структура органов местного самоуправления определяется населением самостоятельно в соответствии с общими принципами организации местного самоуправления в Российской Федерации, установленными федеральным законом.*\n\n11.Органы государственной власти могут участвовать в формировании органов местного самоуправления, назначении на должность и освобождении от должности должностных лиц местного самоуправления в порядке и случаях, установленных федеральным законом.*\n\n2.Изменение границ территорий, в пределах которых осуществляется местное самоуправление, допускается с учетом мнения населения соответствующих территорий в порядке, установленном федеральным законом.*\n\n3.Особенности осуществления публичной власти на территориях городов федерального значения, административных центров (столиц) субъектов Российской Федерации и на других территориях могут устанавливаться федеральным законом.*","article_title":"Статья 131","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b390fca3178a0c70c6aa3c90e98c7039ad7a09958561178b6ced47970043f0c7"},{"code_id":"KONST_RF","article_number":"132","version_date":"1993-12-12","article_text":"1.Органы местного самоуправления самостоятельно управляют муниципальной собственностью, формируют, утверждают и исполняют местный бюджет, вводят местные налоги и сборы, решают иные вопросы местного значения, а также в соответствии с федеральным законом обеспечивают в пределах своей компетенции доступность медицинской помощи.*\n\n2.Органы местного самоуправления могут наделяться федеральным законом, законом субъекта Российской Федерации отдельными государственными полномочиями при условии передачи им необходимых для осуществления таких полномочий материальных и финансовых средств. Реализация переданных полномочий подконтрольна государству.*\n\n3.Органы местного самоуправления и органы государственной власти входят в единую систему публичной власти в Российской Федерации и осуществляют взаимодействие для наиболее эффективного решения задач в интересах населения, проживающего на соответствующей территории.*","article_title":"Статья 132","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2b5a65066d6e6534434773f642ab2d943f5e13d2f7d5e32dde194c54af565d0b"},{"code_id":"KONST_RF","article_number":"133","version_date":"1993-12-12","article_text":"Местное самоуправление в Российской Федерации гарантируется правом на судебную защиту, на компенсацию дополнительных расходов, возникших в результате выполнения органами местного самоуправления во взаимодействии с органами государственной власти публичных функций, а также запретом на ограничение прав местного самоуправления, установленных Конституцией Российской Федерации и федеральными законами.","article_title":"Статья 133","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"55cb5a2e933e4111282bc669ab6f71590c877b81fdd9a69b9c76ee79c537200d"},{"code_id":"KONST_RF","article_number":"134","version_date":"1993-12-12","article_text":"Предложения о поправках и пересмотре положений Конституции Российской Федерации могут вносить Президент Российской Федерации, Совет Федерации, Государственная Дума, Правительство Российской Федерации, законодательные(представительные) органы субъектов Российской Федерации, а также группа численностью не менее одной пятой членов Совета Федерации или депутатов Государственной Думы.","article_title":"Статья 134","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3045b8c0db621c56a9e4ddfc4fa8407fb1416b9186900e7c9a203de8d5b96405"},{"code_id":"KONST_RF","article_number":"135","version_date":"1993-12-12","article_text":"1.Положения глав 1, 2 и 9 Конституции Российской Федерации не могут быть пересмотрены Федеральным Собранием.\n\n2.Если предложение о пересмотре положений глав 1, 2 и 9 Конституции Российской Федерации будет поддержано тремя пятыми голосов от общего числа членов Совета Федерации и депутатов Государственной Думы, то в соответствии с федеральным конституционным законом созывается Конституционное Собрание.\n\n3.Конституционное Собрание либо подтверждает неизменность Конституции Российской Федерации, либо разрабатывает проект новой Конституции Российской Федерации, который принимается Конституционным Собранием двумя третями голосов от общего числа его членов или выносится на всенародное голосование. При проведении всенародного голосования Конституция Российской Федерации считается принятой, если за нее проголосовало более половины избирателей, принявших участие в голосовании, при условии, что в нем приняло участие более половины избирателей.","article_title":"Статья 135","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d4a7f7b6ec64f3e8c2fcdaf066120bfa0914113ce54ee154da623a8c37cbe5ac"},{"code_id":"KONST_RF","article_number":"136","version_date":"1993-12-12","article_text":"Поправки к главам 3 — 8 Конституции Российской Федерации принимаются в порядке, предусмотренном для принятия федерального конституционного закона, и вступают в силу после их одобрения органами законодательной власти не менее чем двух третей субъектов Российской Федерации.","article_title":"Статья 136","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ecba3f388c9019bbe1e7a2df448bc95b3550c77d3bec48cb3b66e6198ca7a346"},{"code_id":"KONST_RF","article_number":"137","version_date":"1993-12-12","article_text":"1.Изменения в статью 65 Конституции Российской Федерации, определяющую состав Российской Федерации, вносятся на основании федерального конституционного закона о принятии в Российскую Федерацию и образовании в ее составе нового субъекта Российской Федерации, об изменении конституционно-правового статуса субъекта Российской Федерации.\n\n2.В случае изменения наименования республики, края, области, города федерального значения, автономной области, автономного округа новое наименование субъекта Российской Федерации подлежит включению в статью 65 Конституции Российской Федерации.","article_title":"Статья 137","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8dada045b7107f640e8319afb03aa22f565a12ed0de897ad6fecd18a942aaa93"}]$law7v020$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text)) insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at) select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
    commit;
